'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={book:'M3 4c4-1 7 0 9 2 2-2 5-3 9-2v15c-4-1-7 0-9 2-2-2-5-3-9-2z M12 6v15',home:'m3 10 9-7 9 7v10H3z M9 20v-7h6v7',shelf:'M4 4v16 M9 4v16 M14 4v16 M18 5l3 14 M2 21h20',explore:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M16 8l-3 5-5 3 3-5z',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M10 3h4l1 3 3 1 3 2v4l-3 1-1 3-2 4h-4l-1-3-3-1-4-2v-4l3-1 1-3z',shield:'M12 3 3 6v6c0 5 9 9 9 9s9-4 9-9V6z M8 12l3 3 5-6',search:'M10.5 3a7.5 7.5 0 1 0 0 15 7.5 7.5 0 0 0 0-15 M16 16l5 5',arrow:'M4 12h16 M15 7l5 5-5 5',back:'M20 12H4 M9 7l-5 5 5 5',chevron:'m9 5 7 7-7 7',down:'m6 9 6 6 6-6',plus:'M12 4v16 M4 12h16',close:'m6 6 12 12 M6 18 18 6',more:'M5 12h.01 M12 12h.01 M19 12h.01',play:'m9 5 11 7-11 7z',pause:'M9 5v14 M15 5v14',stop:'M6 6h12v12H6z',headphones:'M4 14v-3a8 8 0 0 1 16 0v3 M4 12h3v8H4a1 1 0 0 1-1-1v-6z M17 12h3l1 1v6l-1 1h-3z',bookmark:'M6 3h12v18l-6-4-6 4z',check:'m5 12 4 4L19 6',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M12 7v5l3 2',words:'M4 6h16 M4 12h11 M4 18h16',spark:'m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3z',help:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M9 9a3 3 0 1 1 5 2l-2 2 M12 17h.01',leaf:'M20 3C5 2 1 10 6 16s15 2 14-13z M4 21 16 8',upload:'M12 16V3 M7 8l5-5 5 5 M4 16v5h16v-5',download:'M12 3v13 M7 11l5 5 5-5 M4 17v4h16v-4',wifi:'M2 8a15 15 0 0 1 20 0 M5 12a10 10 0 0 1 14 0 M9 16a4 4 0 0 1 6 0 M12 20h.01',lock:'M5 10h14v11H5z M8 10V7a4 4 0 0 1 8 0v3',edit:'m4 16 12-12 4 4L8 20H4z M14 6l4 4',trash:'M3 6h18 M9 6V3h6v3 M6 6l1 15h10l1-15 M10 10v7 M14 10v7',share:'M12 16V3 M7 8l5-5 5 5 M5 12v9h14v-9',sun:'M12 7a5 5 0 1 0 0 10 5 5 0 0 0 0-10 M12 1v2 M12 21v2 M1 12h2 M21 12h2 M4 4l2 2 M18 18l2 2 M4 20l2-2 M18 6l2-2',rewind:'M9 5 2 12l7 7z M21 5l-9 7 9 7z',forward:'m3 5 9 7-9 7z M15 5l7 7-7 7z',volume:'M3 9h4l5-5v16l-5-5H3z M16 8a6 6 0 0 1 0 8 M19 5a10 10 0 0 1 0 14',folder:'M3 6h7l2 3h9v12H3z',people:'M9 4a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M2 21v-3a7 7 0 0 1 14 0v3 M17 4a4 4 0 0 1 0 8 M19 15q3 1 3 6',grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',filter:'M3 4h18l-7 8v7l-4 2v-9z',refresh:'M20 8a8 8 0 1 0 1 7 M20 3v5h-5'};
function icon(name,size=19){return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.55" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.book}"/></svg>`}
function btn(text,action,style='primary',ico=''){return `<button type="button" class="btn ${style}" data-action="${action}">${ico?icon(ico,16):''}${text}</button>`}
function ib(name,action,label){return `<button type="button" class="icon-btn" data-action="${action}" aria-label="${esc(label||name)}" title="${esc(label||name)}">${icon(name)}</button>`}
const seedBooks=[
{id:'secret',title:'The Secret Garden',author:'Frances Hodgson Burnett',color:'#294c43',ink:'#e7d8aa',art:'garden',page:7,total:20,chapter:'The Key to the Garden',genre:'Classics',local:true,summary:'When Mary Lennox discovers a forgotten garden on the Yorkshire moors, a little curiosity begins to transform everything. A timeless story of friendship, healing, and new beginnings.'},
{id:'anne',title:'Anne of Green Gables',author:'L. M. Montgomery',color:'#a9b4a0',ink:'#334a38',art:'house',page:3,total:24,chapter:'A Morning at Green Gables',genre:'Coming of age',local:true,summary:'An imaginative red-haired orphan finds an unexpected home on Prince Edward Island. Follow Anne as she discovers friendship, belonging, and the beauty in ordinary days.'},
{id:'pride',title:'Pride and Prejudice',author:'Jane Austen',color:'#d5bfae',ink:'#5d493e',art:'flower',page:11,total:30,chapter:'Chapter XII',genre:'Romance',local:true,summary:'Wit, misunderstandings, and an unlikely romance unfold in Austen’s beloved portrait of Elizabeth Bennet and Mr. Darcy.'},
{id:'little',title:'Little Women',author:'Louisa May Alcott',color:'#7d3841',ink:'#edd5b1',art:'flower',page:0,total:24,chapter:'Playing Pilgrims',genre:'Family',local:true,summary:'Meet the four March sisters as they navigate friendship, ambition, love, and growing up in Civil War-era New England.'},
{id:'alice',title:'Alice’s Adventures in Wonderland',author:'Lewis Carroll',color:'#b7c6cc',ink:'#344b59',art:'garden',page:0,total:18,chapter:'Down the Rabbit-Hole',genre:'Fantasy',local:true,summary:'A curious girl follows a white rabbit into a wonderfully strange world of impossible things.'},
{id:'island',title:'Treasure Island',author:'Robert Louis Stevenson',color:'#d6aa6a',ink:'#51442e',art:'ship',page:20,total:20,chapter:'Pieces of Eight',genre:'Adventure',local:true,summary:'A mysterious map sends young Jim Hawkins on a sea voyage filled with pirates, hidden treasure, and adventure.'},
{id:'brother',title:'Little Brother',author:'Cory Doctorow',color:'#3b4558',ink:'#d9e0bf',art:'house',page:0,total:22,chapter:'Chapter One',genre:'Science fiction',local:false,summary:'A young technologist questions surveillance and stands up for civil liberties. The featured Content Ratings title includes bundled example classifications.'},
{id:'jungle',title:'The Jungle Book',author:'Rudyard Kipling',color:'#71816a',ink:'#eee2b7',art:'garden',page:0,total:18,chapter:'Mowgli’s Brothers',genre:'Adventure',local:false,summary:'Enter the world of Mowgli, Baloo, and Bagheera in this collection of stories from the Indian jungle.'},
{id:'sherlock',title:'The Adventures of Sherlock Holmes',author:'Arthur Conan Doyle',color:'#444f52',ink:'#d5b992',art:'house',page:0,total:25,chapter:'A Scandal in Bohemia',genre:'Mystery',local:false,summary:'Twelve ingenious mysteries from the world’s most famous consulting detective and his loyal companion Dr. Watson.'}];
const starter=[['fuck','zark','Word start'],['shit','crud','Word start'],['goddamn','darn','Whole word'],['damn','darn','Word start'],['hell','heck','Whole word'],['asshole','jerk','Word start'],['ass','bum','Whole word'],['bastard','jerk','Whole word'],['bitch','jerk','Word start'],['whore','jerk','Word start']].map(([find,replacement,mode],i)=>({id:'starter-'+i,find,replacement,mode,enabled:true,regex:false}));
const today=()=>new Date().toLocaleDateString('en-CA');
const initial={version:1,books:seedBooks,current:'secret',recent:['anne','pride','little'],prefs:{filters:true,highlight:true,redactions:true,highlightRedactions:true,summaries:true,authAdd:false,goal:60,font:'Charter',size:12,tone:'#F8F8F8',mode:'Paged',speed:1,pitch:1,dictionary:'Webster 1828'},filters:starter,bookmarks:{},redacted:{},ranges:{},limits:{},tags:{},pronunciations:{},pin:'',failures:0,stats:{date:today(),seconds:1112,words:4633,total:128450,cleaned:24,cleanedTotal:389},setup:false,resources:{catalog:'ready',dictionary:'ready',kokoro:'missing'},voice:'',engine:'system',tutorials:{}};
let S;try{S=JSON.parse(localStorage.getItem('cleanbooks-prototype-v1'))||structuredClone(initial)}catch{S=structuredClone(initial)}
if(S.stats.date!==today()){S.stats.date=today();S.stats.seconds=0;S.stats.words=0;S.stats.cleaned=0}
let page='home',shelfTab='All books',shelfQuery='',exploreScope='Books',exploreQuery='',reader=null,parent=false,chrome=true,playing=false,pageStarted=0,speechToken=0,modalReturnFocus=null,modalCleanup=null;
const book=id=>S.books.find(b=>b.id===id),localBooks=()=>S.books.filter(b=>b.local),progress=b=>Math.round(b.page/b.total*100),num=n=>n.toLocaleString(),save=()=>{try{localStorage.setItem('cleanbooks-prototype-v1',JSON.stringify(S))}catch{toast('Browser storage is full. Export changes before leaving.')}};
function cover(b,cls=''){b=b||seedBooks[0];return `<div class="cover ${cls}" style="--cover:${b.color};--coverink:${b.ink}" role="img" aria-label="${esc(b.title)} cover"><span class="cover-title">${esc(b.title)}</span>${art(b.art)}<span class="cover-author">${esc(b.author)}</span></div>`}
function art(type){const branches=`<path d="M80 180Q80 90 110 12 M83 145Q35 130 31 78 M88 117Q136 106 151 63 M94 81Q63 66 68 30"/><path d="M82 149Q42 152 34 126Q67 119 82 149 M85 125Q127 134 140 109Q111 98 85 125 M91 91Q44 91 44 65Q77 61 91 91 M99 60Q140 61 143 36Q110 33 99 60 M106 29Q85 10 99 0Q121 7 106 29" fill="currentColor" opacity=".6"/>`;
const types={garden:branches+`<path d="M24 185Q80 157 153 183 M49 180v-19m80 19v-20"/>`,flower:`<path d="M92 190Q79 129 91 48 M91 125Q42 122 40 87Q78 87 91 125 M88 147Q133 144 140 109Q100 107 88 147"/><g transform="translate(93 43)"><path d="M0 0C-60-60-45-90 0-25C45-90 60-60 0 0C75-20 68 18 0 10C43 66 8 76-5 16C-42 76-65 52-12 7C-80 22-78-19-8-7" fill="currentColor" opacity=".35"/><circle r="9" fill="currentColor"/></g>`,house:branches+`<path d="m31 166 51-40 51 40v28H31z" fill="var(--cover)"/><path d="m24 167 58-48 60 48 M40 157v37h83v-37 M72 194v-28h20v28 M45 171h14v12H45"/>`,ship:`<path d="M82 18v143 M77 29Q31 89 23 127h54z M89 45q46 30 47 80H89z M20 155h134l-24 28H45z" fill="currentColor" opacity=".55"/><path d="M4 194q20-13 40 0t40 0 40 0 40 0"/>`};return `<svg class="cover-art" viewBox="0 0 180 210" fill="none" stroke="currentColor" stroke-width="1.5">${types[type]||types.garden}</svg>`}
function bar(n){return `<div class="progress"><span style="width:${Math.min(100,n)}%"></span></div>`}
function navButton(id,label,ico){return `<button data-action="nav:${id}" class="${page===id?'active':''}">${icon(ico)}<span>${label}</span>${id==='shelf'?`<span class="count">${localBooks().length}</span>`:''}</button>`}
function render(){const titles={home:'Home',shelf:'Bookshelf',explore:'Explore',settings:'Settings',filters:'Edit Filters'};$('#app').innerHTML=`<aside class="sidebar"><a class="brand" href="#home" data-action="nav:home" style="text-decoration:none"><span class="brand-icon">${icon('book',24)}</span>Clean Books</a><div class="brand-caption">A LITTLE PEACE. EVERY PAGE.</div><nav class="nav" aria-label="Main navigation">${navButton('home','Home','home')}${navButton('shelf','Bookshelf','shelf')}${navButton('explore','Explore','explore')}${navButton('settings','Settings','settings')}</nav><div class="side-label">YOUR READING, YOUR WAY</div><button class="side-link" data-action="guard-filters">${icon('shield',17)}Word filters</button><button class="side-link" data-action="help">${icon('help',17)}Help & tutorials</button><div class="sidebar-bottom"><div class="local-note"><strong>${icon('leaf',15)} A library that’s yours.</strong>Your books and preferences stay right here, on your device.</div><div class="profile"><div class="avatar">R</div><div><strong>My reading space</strong><p>Personal library</p></div>${ib('more','prototype','Prototype controls')}</div></div></aside><main class="main"><header class="topbar"><div class="breadcrumb">My reading space ${icon('chevron',12)} <span style="color:#596d57">${titles[page]}</span></div><div class="mobile-brand brand"><span class="brand-icon">${icon('book',22)}</span>Clean Books</div><div class="top-actions"><button class="search-top" data-action="global-search" aria-label="Find your next read">${icon('search',16)}<span>Find your next read</span><span class="key">⌘ K</span></button><span class="status"><span class="status-dot"></span>${navigator.onLine?'Saved on this device':'Offline · local library ready'}</span>${ib('help','help','Help & tutorials')}</div></header><div class="content">${({home:homeView,shelf:shelfView,explore:exploreView,settings:settingsView,filters:filtersView}[page]||homeView)()}</div></main><nav class="mobile-nav" aria-label="Main navigation">${[['home','Home','home'],['shelf','Bookshelf','shelf'],['explore','Explore','explore'],['settings','Settings','settings']].map(([id,label,ico])=>`<button class="${page===id?'active':''}" data-action="nav:${id}">${icon(ico,21)}${label}</button>`).join('')}</nav>${reader?readerView():''}`;$$('aside.sidebar,main.main,nav.mobile-nav').forEach(el=>el.inert=!!reader);$('#app').inert=!!$('.modal');if(reader&&S.prefs.mode==='Scroll')requestAnimationFrame(()=>{let el=$('#reader-body');if(el)el.scrollTop=S.scrollPositions?.[reader.id+':'+reader.page]||0});save()}
function heading(title,desc,action=''){return `<div class="page-heading"><div><h1>${title}</h1><p>${desc}</p></div>${action}</div>`}
function homeView(){const b=book(S.current)?.local?book(S.current):null;let pct=Math.min(1,S.stats.seconds/(S.prefs.goal*60));return `${heading('A good day for a good book.','Settle in. Your next chapter is waiting.',`<div class="date-note">${new Date().toLocaleDateString('en-US',{weekday:'long',month:'long',day:'numeric'})}</div>`)}<section class="home-top"><div class="now-reading"><div class="eyebrow">${icon('book',13)} &nbsp; NOW READING</div>${b?`<div class="hero-body">${cover(b,'hero-cover')}<div class="hero-copy"><h2>${esc(b.title)}</h2><p class="author">${esc(b.author||'Anonymous')}</p><p class="chapter">Chapter ${b.page+1} · ${esc(b.chapter)}</p>${bar(progress(b))}<div class="progress-label"><span>${progress(b)}% complete</span><span>${Math.max(0,b.total-b.page)} chapters left</span></div><div class="flex">${btn('Resume reading','read:'+b.id,'primary','book')}<span class="pill">${icon('shield',11)} ${S.prefs.filters&&!b.excluded?'Filters on':'Filters paused'}</span></div></div></div>`:`<div style="margin:auto"><h2>Pick your next read</h2><p class="muted" style="margin:15px 0">A whole world of stories is waiting for you.</p>${btn('Browse library','nav:explore','primary','explore')}</div>`}</div><div class="card daily"><div class="card-head"><h3>Daily Reading</h3><button class="text-btn" data-action="goal">${S.prefs.goal} min goal ${icon('edit',12)}</button></div><div class="circle"><svg viewBox="0 0 140 140"><circle cx="70" cy="70" r="60" fill="none" stroke="#edf1e8" stroke-width="7"/><circle cx="70" cy="70" r="60" fill="none" stroke="#91a978" stroke-width="7" stroke-linecap="round" stroke-dasharray="${pct*377} 377"/></svg><div class="circle-copy"><strong>${Math.floor(S.stats.seconds/60)}<span style="font-size:20px;opacity:.55">:${String(S.stats.seconds%60).padStart(2,'0')}</span></strong><small>of ${S.prefs.goal} minutes</small></div></div><p class="daily-caption">${pct>=1?'You reached your daily goal. Well read!':'A few quiet minutes go a long way.'}</p><div class="week" aria-label="Sample reading week">${['M','T','W','T','F','S','S'].map((d,i)=>`<div>${d}<i class="${i<4?'done':i===5?'today':''}">${i<4?icon('check',10):i===5?'·':''}</i></div>`).join('')}</div></div></section><section class="card stats-row" aria-label="Reading Statistics">${[['words',num(S.stats.total),'words','All-time words read'],['book',num(S.stats.words),'words','Words read today'],['clock','250','wpm','Average reading speed']].map(([i,v,u,l])=>`<div class="stat"><div class="stat-icon">${icon(i,21)}</div><div><strong>${v}</strong><span class="unit">${u}</span><p>${l}</p></div></div>`).join('')}</section><section><div class="section-title"><h2>Recent books <span class="small">A few familiar worlds</span></h2><button class="text-btn" data-action="nav:shelf">View bookshelf ${icon('arrow',15)}</button></div><div class="recent-grid">${S.recent.map(book).filter(b=>b?.local&&b.id!==S.current).slice(0,3).map(b=>`<button class="card recent-card" data-action="read:${b.id}">${cover(b)}<div><h3>${esc(b.title)}</h3><p>${esc(b.author)}</p>${bar(progress(b))}<span class="small">${b.page?progress(b)+'% read':'Not started yet'}</span></div></button>`).join('')||'<p class="muted">Open another book to keep it close by here.</p>'}</div></section><section class="discovery-banner"><div class="discovery-icon">${icon(S.setup?'explore':'leaf',23)}</div><div><h3>${S.setup?'Find a story worth getting lost in.':'Your reading space, made for you.'}</h3><p>${S.setup?'Discover timeless stories in the Project Gutenberg collection.':'A quick setup for cleaner words, comfortable reading, and peace of mind.'}</p></div><button class="text-btn" data-action="${S.setup?'nav:explore':'tour:0'}">${S.setup?'Explore the collection':'Make it yours'} ${icon('arrow',16)}</button></section><footer class="footer"><span>${icon('leaf',11)} &nbsp; A little more peace on every page.</span><span>Sample library & activity</span></footer>`}
function bookCard(b,explore=false){return `<article class="book-card"><div class="book-art" style="background:${b.color}10"><button class="open-book" data-action="${explore?'detail:':'read:'}${b.id}" aria-label="${explore?'View':'Read'} ${esc(b.title)}">${cover(b)}</button>${!explore?ib('more','review:'+b.id,'Book options — '+b.title):''}</div><h3><button data-action="${explore?'detail:':'read:'}${b.id}" style="padding:0;text-align:left">${esc(b.title)}</button></h3><p>${esc(b.author)}</p>${!explore?`${bar(progress(b))}<div class="book-meta"><span>${b.page===b.total?'COMPLETE':b.page?progress(b)+'% READ':'NEW'}</span>${icon(b.excluded?'book':'shield',13)}</div>`:`<div class="book-meta"><span>${esc(b.genre)}</span><span>${b.local?'In your library':'Free EPUB'} ${icon(b.local?'check':'download',12)}</span></div>`}</article>`}
function shelfView(){let books=localBooks().filter(b=>(shelfTab==='All books'||shelfTab==='Reading'&&b.page>0&&b.page<b.total||shelfTab==='Unread'&&!b.page||shelfTab==='Finished'&&b.page===b.total)&&`${b.title} ${b.author}`.toLowerCase().includes(shelfQuery.toLowerCase()));return `${heading('Your bookshelf.','Stories to return to. Worlds to discover.',btn('Add Book','add-book','primary','plus'))}<div class="toolbar"><div class="tabs">${['All books','Reading','Unread','Finished'].map(t=>`<button class="${shelfTab===t?'active':''}" data-action="shelf-tab:${t}">${t}${t==='All books'?' · '+localBooks().length:''}</button>`).join('')}</div><label class="search-field">${icon('search',16)}<input id="shelf-search" aria-label="Search your library" placeholder="Search your library" value="${esc(shelfQuery)}"></label></div><div class="book-grid" id="shelf-results">${books.map(b=>bookCard(b)).join('')}</div>${!books.length?empty('shelf',shelfQuery?'No books found':'A little room for a new story.',shelfQuery?'Try another title or author.':'Add an EPUB or explore the collection.',btn('Explore books','nav:explore')):''}<footer class="footer"><span>${localBooks().length} books · Available on this device</span><span>${icon('shield',11)} Your books. Your preferences.</span></footer>`}
function empty(i,t,d,action=''){return `<div class="empty">${icon(i,38)}<h2>${t}</h2><p>${d}</p>${action}</div>`}
function exploreView(){return `${heading('Find your next chapter.','Timeless books. Endless possibilities. Always yours to read.',btn('Search Gutenberg','global-search','secondary','search'))}${S.resources.catalog!=='ready'?`<div class="card">${empty('download','The library is preparing',S.resources.catalog==='failed'?'The catalog download failed. Your local books are still available.':'The Project Gutenberg catalog needs its first download (70.8 MB).',btn('Retry Download','resource:catalog'))}</div>`:`<div class="explore-hero"><div><div class="eyebrow muted" style="margin-bottom:15px">THE TIMELESS COLLECTION</div><h2>Some stories stay with you forever.</h2><p>Rediscover the classics that spark imagination. Make your next great read a little more you.</p>${btn('Browse popular reads','browse:Books','primary','arrow')}</div><div class="explore-art">${cover(book('anne'))}${cover(book('little'))}</div></div><div class="browse-tiles">${[['Books','Popular reads','book'],['Authors','Browse writers','people'],['Subjects','Explore topics','folder'],['Collections','Curated shelves','grid']].map(([t,d,i])=>`<button class="browse-tile" data-action="browse:${t}">${icon(i,22)}<div><strong>${t}</strong><small>${d}</small></div></button>`).join('')}</div><div class="section-title"><h2>Stories for your shelf</h2><button class="text-btn" data-action="browse:Books">See all ${icon('arrow',15)}</button></div><div class="book-grid">${['anne','little','jungle','sherlock'].map(id=>bookCard(book(id),true)).join('')}</div><div class="discovery-banner"><div class="discovery-icon">${icon('shield',22)}</div><div><h3>A thoughtful way to turn the page.</h3><p>Try Content Ratings with Little Brother by Cory Doctorow.</p></div><button class="text-btn" data-action="detail:brother">Discover content review ${icon('arrow',15)}</button></div>`}<footer class="footer"><span>Project Gutenberg · Public-domain discovery sample</span><span>Catalog browsing and downloads are simulated in this prototype</span></footer>`}
function toggle(key){return `<button role="switch" aria-checked="${!!S.prefs[key]}" aria-label="${esc(key)}" class="toggle ${S.prefs[key]?'on':''}" data-action="toggle:${key}"><span></span></button>`}
function setting(title,desc,control){return `<div class="setting-row"><div><strong>${title}</strong>${desc?`<p>${desc}</p>`:''}</div>${control}</div>`}
function row(i,t,d,action){return `<button class="row-action" data-action="${action}">${icon(i,20)}<span class="row-text"><strong>${t}</strong>${d?`<p>${d}</p>`:''}</span>${icon('chevron',14)}</button>`}
function settingsView(){return `${heading('A little more you.','Thoughtful preferences for your reading space.')}<div class="settings-layout"><div class="stack"><section class="card settings-group"><div class="flex between"><h3>${icon('shield',18)} &nbsp; Cleaner reading</h3><span class="pill">${S.prefs.filters?'Active':'Paused'}</span></div>${setting('Word filtering','Replace selected words while you read and listen.',toggle('filters'))}${row('edit','Edit Filters',`${S.filters.filter(f=>f.enabled).length} active rules · Updated on this device`,'filters')}${setting('Highlight Filter Matches','A soft highlight on cleaned words.',toggle('highlight'))}${setting('Text Redactions','Hide marked passages and content above your limits.',toggle('redactions'))}${setting('Highlight Redacted Text',S.prefs.redactions?'Available when Text Redactions is off.':'Highlight marked passages when visible.',`<button role="switch" aria-label="Highlight Redacted Text" aria-checked="${S.prefs.highlightRedactions}" class="toggle ${S.prefs.highlightRedactions?'on':''}" ${S.prefs.redactions?'disabled':''} data-action="toggle:highlightRedactions"><span></span></button>`)}</section><section class="card settings-group"><h3>${icon('lock',18)} &nbsp; Parent protection</h3>${setting('PIN Authentication',S.pin?'Protected editing is enabled.':'Protect your filters, content review, and editing tools.',btn(S.pin?'Manage PIN':'Set up PIN','pin-manage','secondary','lock'))}${setting('Authenticate Before Adding Filters','Also protect new filters added from a word.',toggle('authAdd'))}</section><section class="card settings-group"><details><summary style="cursor:pointer;font-size:13px;font-weight:550;padding:3px 0">Additional Settings</summary>${setting('AI Paragraph Summaries','Requires iOS 26+ and compatible Apple Intelligence.',toggle('summaries'))}${setting('Definition Dictionary','Your preferred source for word meanings.',`<select data-pref="dictionary" aria-label="Definition Dictionary">${['Webster 1828','System Dictionary'].map(x=>`<option ${x===S.prefs.dictionary?'selected':''}>${x}</option>`).join('')}</select>`)}${row('download','Resources & downloads','Catalog, dictionary, and local voices','resources')}</details></section></div><div class="stack"><section class="card settings-group"><div class="eyebrow muted">SMALL CHANGES. GOOD HABITS.</div><h2 style="margin:13px 0 8px">Make time for a story.</h2><p class="muted small">Your daily goal is a gentle invitation to slow down and read a little.</p>${setting('Daily Reading Goal','Minutes of reading each day',`<select data-pref="goal" aria-label="Daily Reading Goal">${[15,30,45,60].map(n=>`<option value="${n}" ${S.prefs.goal===n?'selected':''}>${n} minutes</option>`).join('')}</select>`)}</section><section class="card settings-group"><h3>A few words, a little cleaner.</h3><div class="review-metrics" style="grid-template-columns:1fr 1fr"><div><strong>${num(S.stats.cleaned)}</strong><small>cleaned today</small></div><div><strong>${num(S.stats.cleanedTotal)}</strong><small>cleaned all-time</small></div></div><p class="muted small">Separate from your reading word totals.</p></section><section class="card settings-group">${row('help','Help & Tutorials','A little guidance, whenever you need it.','help')}${row('leaf','App Setup Tour','Make this space yours in six easy steps.','tour:0')}</section><p class="small muted" style="padding:0 10px">Clean Books · Your reading space<br>Preferences are saved on this device.</p></div></div>`}
function filtersView(){return `${heading('Words, on your terms.','Small replacements. A more comfortable story.',btn('Add Filter','filter-new','primary','plus'))}<div class="toolbar"><span class="muted small">${S.filters.filter(f=>f.enabled).length} of ${S.filters.length} rules active</span><div class="flex">${S.filters.some(f=>!f.enabled)?btn('Enable All','filters-enable','secondary'):''}${btn('Share Filters','export:filters','secondary','share')}${ib('more','filter-more','More filter actions')}</div></div>${S.filters.length?`<div class="card filter-list">${S.filters.map(f=>`<div class="filter-row"><button role="switch" aria-label="Enable ${esc(f.find)}" aria-checked="${f.enabled}" class="toggle ${f.enabled?'on':''}" data-action="filter-toggle:${f.id}"><span></span></button><button class="filter-word" style="text-align:left" data-action="filter-edit:${f.id}">${esc(f.find)}<small>${f.regex?'Custom regex':f.mode}</small></button>${icon('arrow',15)}<span class="replacement">${esc(f.replacement)}</span>${ib('edit','filter-edit:'+f.id,'Edit '+f.find)}${ib('trash','filter-delete:'+f.id,'Delete '+f.find)}</div>`).join('')}</div>`:empty('shield','No filters yet','Keep the story. Choose the words that feel right.',btn('Add Your First Filter','filter-new'))}<div class="note" style="margin-top:20px">${icon('leaf',16)} Rules apply to reading and read-aloud playback. Excluding one book keeps your global rules intact.</div>`}
function go(dest){if(dest==='settings'&&page!=='settings')return guard(()=>{page=dest;render();window.scrollTo(0,0)});page=dest;render();window.scrollTo(0,0)}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),3300)}
function modal(title,body,wide=false){$('#app').inert=true;if(modalCleanup){modalCleanup();modalCleanup=null}const old=$('.modal');if(!old)modalReturnFocus=document.activeElement;$('#modal-root').innerHTML=`<div class="modal-backdrop"><section role="dialog" aria-modal="true" aria-labelledby="modal-title" class="modal ${wide?'wide':''}"><header class="modal-header"><h2 id="modal-title">${title}</h2>${ib('close','close','Close dialog')}</header><div class="modal-body">${body}</div></section></div>`;requestAnimationFrame(()=>$('.modal input:not([type=checkbox]),.modal button')?.focus())}
function closeModal(){if(modalCleanup){modalCleanup();modalCleanup=null}$('#modal-root').innerHTML='';$('#app').inert=false;modalReturnFocus?.focus?.();modalReturnFocus=null}
function confirmAction(title,message,label,fn){modal(title,`<p class="muted">${message}</p><div class="modal-footer">${btn('Cancel','close','secondary')}<button class="btn primary danger" id="confirm-action">${label}</button></div>`);$('#confirm-action').onclick=()=>{closeModal();fn();save();render()}}
function guard(fn){if(!S.pin)return fn();let challenge=S.failures>=3?Array.from({length:4},()=>Math.floor(Math.random()*10)).join(''):'';modal('Unlock parent tools',`<div class="tour-art">${icon('lock',50)}</div><p class="muted small" style="margin-bottom:18px">Enter your 4-digit PIN to continue. Reading is always available without it.</p>${challenge?`<div class="note" id="challenge-note">First type these four challenge digits: <strong>${challenge}</strong></div>`:''}<form id="auth-form"><label class="field">${challenge?'Challenge digits':'Your PIN'}<input class="pin-input" id="auth-pin" type="password" inputmode="numeric" pattern="[0-9]{4}" maxlength="4" required autocomplete="off"></label><p class="error" id="auth-error"></p><div class="modal-footer">${btn('Cancel','close','secondary')}<button class="btn primary">Unlock</button></div></form>`);$('#auth-form').onsubmit=e=>{e.preventDefault();let v=$('#auth-pin').value;if(challenge){if(v!==challenge){$('#auth-error').textContent='Those challenge digits did not match.';return}challenge='';$('#challenge-note').remove();$('#auth-form label').firstChild.textContent='Your PIN';$('#auth-pin').value='';$('#auth-pin').focus();return}if(v!==S.pin){S.failures++;save();if(S.failures===3)return guard(fn);$('#auth-error').textContent='Incorrect PIN. Try again.';$('#auth-pin').value='';return}let fails=S.failures;S.failures=0;save();closeModal();if(fails)toast(`${fails} unsuccessful attempt${fails===1?'':'s'} since the last unlock.`);fn()}}
function pinSetup(){let fromTour=$('#modal-title')?.textContent==='App Setup Tour';modal('Set up PIN',`<p class="muted small" style="margin-bottom:20px">Choose a 4-digit PIN for protected editing. This prototype stores it locally for demonstration; do not use a real security PIN.</p><form id="pin-form"><label class="field">New PIN<input id="new-pin" type="password" class="pin-input" inputmode="numeric" pattern="[0-9]{4}" maxlength="4" required></label><label class="field">Confirm PIN<input id="confirm-pin" type="password" class="pin-input" inputmode="numeric" pattern="[0-9]{4}" maxlength="4" required></label><p class="error" id="pin-error"></p><div class="modal-footer">${btn('Cancel','close','secondary')}<button class="btn primary">Save PIN</button></div></form>`);$('#pin-form').onsubmit=e=>{e.preventDefault();if($('#new-pin').value!==$('#confirm-pin').value){$('#pin-error').textContent='The PINs do not match.';return}S.pin=$('#new-pin').value;S.failures=0;save();closeModal();render();if(fromTour)tour(2);toast('Parent protection is now on.')}}
const secretParagraphs=[
'When Mary Lennox was sent to Misselthwaite Manor to live with her uncle everybody said she was the most disagreeable-looking child ever seen. It was true, too. She had a little thin face and a little thin body, thin light hair and a sour expression.',
'One of the nice little gusts of wind rushed down the walk, and it was a stronger one than the rest. It was strong enough to wave the branches of the trees, and it was more than strong enough to sway the trailing sprays of untrimmed ivy hanging from the wall.',
'Mary had stepped close to the robin, and suddenly the gust of wind swung aside some loose ivy trails, and more suddenly still she jumped toward it and caught it in her hand. This she did because she had seen something under it—a round knob which had been covered by the leaves hanging over it. It was the knob of a door.',
'She put her hands under the leaves and began to pull and push them aside. Thick as the ivy hung, it nearly all was a loose and swinging curtain, though some had crept over wood and iron. Mary’s heart began to thump and her hands to shake a little in her delight and excitement.',
'The robin kept singing and twittering away and tilting his head on one side, as if he were as excited as she was. What was this under her hands which was square and made of iron and which her fingers found a hole in?',
'It was the lock of the door which had been closed ten years and she put her hand in her pocket, drew out the key and found it fitted the keyhole. She put the key in and turned it. It took two hands to do it, but it did turn.',
'And then she took a long breath and looked behind her up the long walk to see if anyone was coming. No one was coming. No one ever did come, it seemed, and she took another long breath, because she could not help it, and she held back the swinging curtain of ivy and pushed back the door which opened slowly—slowly.',
'Then she slipped through it, and shut it behind her, and stood with her back against it, looking about her and breathing quite fast with excitement, and wonder, and delight. She was standing inside the secret garden.'
];
const excerpts={anne:['Mrs. Rachel Lynde lived just where the Avonlea main road dipped down into a little hollow, fringed with alders and ladies’ eardrops and traversed by a brook that had its source away back in the woods of the old Cuthbert place.','It was a busy afternoon in the pleasant farmhouse. The orchard was a drift of pinky-white bloom, hummed over by a myriad of bees. In the west the sky glowed with a warm and wonderful light.','Matthew Cuthbert and the sorrel mare jogged comfortably over the eight miles to Bright River. It was a pretty road, running along between snug farmsteads, with now and again a bit of balsamy fir wood to drive through.'],pride:['It is a truth universally acknowledged, that a single man in possession of a good fortune, must be in want of a wife.','However little known the feelings or views of such a man may be on his first entering a neighbourhood, this truth is so well fixed in the minds of the surrounding families, that he is considered as the rightful property of some one or other of their daughters.','“My dear Mr. Bennet,” said his lady to him one day, “have you heard that Netherfield Park is let at last?” Mr. Bennet replied that he had not.'],little:['“Christmas won’t be Christmas without any presents,” grumbled Jo, lying on the rug.','“It’s so dreadful to be poor!” sighed Meg, looking down at her old dress.','“I don’t think it’s fair for some girls to have plenty of pretty things, and other girls nothing at all,” added little Amy, with an injured sniff.','“We’ve got Father and Mother, and each other,” said Beth contentedly from her corner.'],alice:['Alice was beginning to get very tired of sitting by her sister on the bank, and of having nothing to do: once or twice she had peeped into the book her sister was reading, but it had no pictures or conversations in it.','So she was considering in her own mind whether the pleasure of making a daisy-chain would be worth the trouble of getting up and picking the daisies, when suddenly a White Rabbit with pink eyes ran close by her.'],island:['Squire Trelawney, Dr. Livesey, and the rest of these gentlemen having asked me to write down the whole particulars about Treasure Island, from the beginning to the end, keeping nothing back but the bearings of the island, I take up my pen in the year of grace 17— and go back to the time when my father kept the Admiral Benbow inn.','I remember him as if it were yesterday, as he came plodding to the inn door, his sea-chest following behind him in a hand-barrow—a tall, strong, heavy, nut-brown man, his tarry pigtail falling over the shoulder of his soiled blue coat.']};
function paragraphs(b,p=b.page){if(b.chapters)return b.chapters[Math.min(p,b.chapters.length-1)]?.paragraphs||[];if(b.id==='secret')return p%2?secretParagraphs:secretParagraphs.slice(4).concat(secretParagraphs.slice(0,4));return excerpts[b.id]||['This is a sample reading passage for the interactive prototype. Open a local EPUB from Bookshelf to read your own book, or explore the reader’s appearance, voice, bookmarks, and protected editing controls.','A good story invites us to slow down, to notice the world, and to look at familiar things in a new way. There is always another chapter waiting.']}
function chapterTitle(b,p=b.page){return b.chapters?.[p]?.title||(p===b.page?b.chapter:`Chapter ${p+1}`)}
function locKey(b,p,i){return `${p}:${i}`}
function getTags(b,p,i){let key=locKey(b,p,i);return S.tags[b.id]?.[key]||[]}
function isBlocked(b,p,i){return getTags(b,p,i).some(t=>t.severity>({Blocked:10,Mild:39,Moderate:79,Strong:100}[S.limits[b.id]?.[t.category]||'Strong']))}
function isRedacted(b,p,i){return S.redacted[b.id]?.includes(locKey(b,p,i))||isBlocked(b,p,i)}
function filterRegex(f){let literal=f.find.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');let source=f.regex?f.find:literal;let start=f.mode==='Whole word'||f.mode==='Word start'||f.start,end=f.mode==='Whole word'||f.mode==='Word end'||f.end;return new RegExp(`${start?'\\b':''}(?:${source})${end?'\\b':''}`,'gi')}
function cleanText(text,b,markup=false){if(!S.prefs.filters||b?.excluded)return markup?esc(text):text;let rules=S.filters.filter(f=>f.enabled).slice().sort((a,b)=>Number(a.regex)-Number(b.regex)||b.find.length-a.find.length);let matches=[];for(const f of rules){try{for(const match of text.matchAll(filterRegex(f))){if(!match[0].length)continue;let start=match.index,end=start+match[0].length;if(matches.some(m=>start<m.end&&end>m.start))continue;let replacement=f.replacement;replacement=match[0][0]===match[0][0].toUpperCase()?replacement[0].toUpperCase()+replacement.slice(1):replacement[0].toLowerCase()+replacement.slice(1);matches.push({start,end,replacement})}}catch{}}matches.sort((a,b)=>a.start-b.start);let out='',pos=0;for(const m of matches){out+=markup?esc(text.slice(pos,m.start)):text.slice(pos,m.start);out+=markup?`<span class="${S.prefs.highlight?'cleaned':''}">${esc(m.replacement)}</span>`:m.replacement;pos=m.end}return out+(markup?esc(text.slice(pos)):text.slice(pos))}
function paragraphMarkup(text,b,p,i){if(S.prefs.redactions&&!parent&&isRedacted(b,p,i))return `<p class="redacted" data-action="summary">${icon('shield',15)}<span>Passage hidden · Your reading preferences</span>${icon('lock',12)}</p>`;let key=locKey(b,p,i),ranges=S.ranges[b.id]?.[key]||[];if(ranges.length&&!parent&&S.prefs.redactions){let result='',cursor=0;for(const r of ranges.slice().sort((a,b)=>a.start-b.start)){result+=cleanText(text.slice(cursor,r.start),b,true)+`<span class="cleaned" aria-label="Redacted text">•••</span>`;cursor=r.end}return `<p data-paragraph="${i}">${result+cleanText(text.slice(cursor),b,true)}</p>`}let content=cleanText(text,b,true);return `<p class="${parent?'editable':''}" data-paragraph="${i}" ${parent?`data-action="paragraph:${i}"`:''} style="${!S.prefs.redactions&&S.prefs.highlightRedactions&&isRedacted(b,p,i)?'background:#dcd7ba55':''}">${content}${parent&&isRedacted(b,p,i)?` <span class="pill orange">Hidden in reader</span>`:''}</p>`}
function openReader(id){speechOffset=0;const b=book(id);if(!b?.local)return;stopSpeech();closeModal();if(S.current&&S.current!==id)S.recent=[S.current,...S.recent.filter(x=>x!==S.current&&x!==id)].slice(0,3);S.current=id;reader={id,page:Math.min(b.page,b.total-1),review:false};parent=false;chrome=false;pageStarted=Date.now();save();render();setTimeout(()=>{if(reader&&!parent){chrome=true;render()}},1600)}
function readerView(){let b=book(reader.id),p=reader.page,ps=paragraphs(b,p);const dark=['#373737','#000000'].includes(S.prefs.tone);let marked=(S.bookmarks[b.id]||[]).some(x=>x.page===p);return `<section class="reader ${!chrome&&!parent?'chrome-hidden':''}" style="--page:${S.prefs.tone};--page-ink:${dark?'#F2F2F2':'#1A1A1A'};--reader-font:'${S.prefs.font}';--reader-size:${S.prefs.size*1.5}px;background:var(--page);color:var(--page-ink)"><header class="reader-header">${ib('back','reader-close','Back to library')}<div class="reader-title"><h3>${esc(b.title)}</h3><p>${reader.review?'PASSAGE REVIEW · Position not saved':esc(b.author)}</p></div><div class="flex">${parent?ib('shield','parent-tools','Parent tools'):''}${ib('bookmark','bookmark',marked?'Remove bookmark':'Bookmark page')}${ib('more','reader-menu','Reader menu')}</div></header>${parent?`<div class="parent-bar">${icon('shield',14)} Parent Edit Mode · Tap a paragraph to edit <button class="text-btn" data-action="parent-exit">Exit edit mode</button></div>`:''}${reader.review?`<div class="parent-bar">Temporary review · Your reading position is preserved ${btn('Open Book Here','open-here','soft','book')}</div>`:''}<div class="reader-body" id="reader-body"><article class="reading-page"><div class="eyebrow">${b.chapters?'CHAPTER':'SAMPLE EXCERPT · CHAPTER'} ${p+1}</div><h1>${esc(chapterTitle(b,p))}</h1>${ps.map((t,i)=>paragraphMarkup(t,b,p,i)).join('')}${S.prefs.mode==='Scroll'?`<div style="text-align:center;margin:35px">${p<b.total-1?btn('Next chapter','reader-next','soft','arrow'):'End of Book'}</div>`:''}<div class="reader-hint">${parent?'Tap a paragraph for redaction options.':'Tap the page to show or hide controls. Long-press a word for more.'}</div></article></div><footer class="reader-footer"><div class="audio-controls">${ib('headphones','voices','Choose Voice')}${ib('rewind','skip-back','Skip back 10 seconds')}<button class="play-button" data-action="play" aria-label="${playing?'Pause':'Read aloud'}">${icon(playing?'pause':'play',18)}</button>${ib('forward','skip-forward','Skip forward 10 seconds')}${ib('stop','speech-stop','Stop playback')}<select aria-label="Reading speed" data-pref="speed">${[.3,.5,.7,.85,1,1.2,1.5,2].map(x=>`<option value="${x}" ${S.prefs.speed===x?'selected':''}>${x}×</option>`).join('')}</select></div><span class="small">${progress({...b,page:p})}% complete · ${S.engine==='system'?'System voice':'Kokoro unavailable in browser'}</span><div class="page-nav">${ib('back','reader-prev','Previous chapter')}<span class="small">${p+1} / ${b.total}</span>${ib('arrow','reader-next','Next chapter')}</div></footer></section>`}
function creditReading(){if(!reader||reader.review||parent)return;let text=paragraphs(book(reader.id),reader.page).join(' '),words=text.split(/\s+/).length,elapsed=(Date.now()-pageStarted)/1000,minimum=Math.max(2,words/10);if(elapsed>=minimum){let expected=words/250*60,credited=elapsed>expected*2.5?expected:elapsed;S.stats.seconds+=Math.round(credited);S.stats.words+=words;S.stats.total+=words;let b=book(reader.id);let changes=paragraphs(b,reader.page).reduce((n,t,i)=>n+(!isRedacted(b,reader.page,i)?(cleanText(t,b,true).match(/<span/g)||[]).length:0),0);S.stats.cleaned+=changes;S.stats.cleanedTotal+=changes}pageStarted=Date.now()}
function turnPage(delta){if(!reader)return;const b=book(reader.id),p=Math.max(0,Math.min(b.total-1,reader.page+delta));if(p===reader.page)return toast(delta>0?'End of Book':'You’re at the beginning.');creditReading();let wasPlaying=playing;stopSpeech();reader.page=p;speechOffset=0;if(!reader.review){b.page=p;save()}pageStarted=Date.now();chrome=true;render();if(wasPlaying)playSpeech()}
function readerMenu(){modal('Your reading tools',`${row('book','Contents and bookmarks','Jump to a chapter or a saved moment.','contents')}${row('bookmark',(S.bookmarks[reader.id]||[]).some(x=>x.page===reader.page)?'Remove bookmark':'Bookmark page','Keep your place close by.','bookmark')}${row('headphones','Choose Voice','Voice Reading · System and Premium Voices','voices')}${row('words','Custom Pronunciations','Change how words sound, not how they look.','pronunciations')}${row('sun','Reader settings','Type, page tone, and reading movement.','appearance')}${row('shield',parent?'Exit Parent Edit Mode':'Enter parent edit mode','Review passages and make thoughtful changes.',parent?'parent-exit':'parent-enter')}`)}
function parentTools(){modal('Parent tools',`${row('search','Search book','Find and review a passage.','book-search')}${row('edit','Manage redactions','Whole passages and selected text.','redactions')}${row('filter','Review filtered words','See the active replacements in this book.','review-words')}${row('shield','Review content','Categories, content limits, and book actions.','review:'+reader.id)}${row('book',book(reader.id).excluded?'Add to Filtering':'Remove from Filtering','','exclude:'+reader.id)}${row('check','Exit edit mode','','parent-exit')}`)}
function bookmark(){const b=book(reader.id);let a=S.bookmarks[b.id]||[],i=a.findIndex(x=>x.page===reader.page);if(i>=0)a.splice(i,1);else a.push({page:reader.page,snippet:paragraphs(b,reader.page)[0].slice(0,100),chapter:chapterTitle(b,reader.page)});S.bookmarks[b.id]=a;save();closeModal();render();toast(i>=0?'Bookmark removed':'Page bookmarked')}
function contents(tab='Contents'){const b=book(reader.id);let list=tab==='Contents'?Array.from({length:b.total},(_,i)=>`<button class="row-action" data-action="chapter:${i}"><span class="muted small" style="width:24px">${String(i+1).padStart(2,'0')}</span><span class="row-text"><strong>${esc(chapterTitle(b,i))}</strong></span>${reader.page===i?`<span class="pill">Reading</span>`:icon('chevron',13)}</button>`).join(''):(S.bookmarks[b.id]||[]).map((x,i)=>`<div class="flex"><button class="row-action" data-action="chapter:${x.page}"><span class="row-text"><strong>${esc(x.chapter)}</strong><p>${esc(x.snippet)}…</p><small class="muted">Chapter ${x.page+1}</small></span></button>${ib('trash','bookmark-delete:'+i,'Delete bookmark')}</div>`).join('')||empty('bookmark','No bookmarks yet.','Save a page from the reader to keep it here.');modal('Contents and bookmarks',`<div class="tabs">${['Contents','Bookmarks'].map(x=>`<button class="${x===tab?'active':''}" data-action="contents-tab:${x}">${x}</button>`).join('')}</div>${list}`)}
function appearance(){modal('Reader settings',`<div class="appearance-preview" id="appearance-preview" style="font-family:'${S.prefs.font}',Georgia,serif;font-size:${S.prefs.size*1.5}px;background:${S.prefs.tone};color:${['#373737','#000000'].includes(S.prefs.tone)?'#f2f2f2':'#1a1a1a'}">A little more peace on every page.</div><div class="setting-row"><strong>Text size</strong><div class="flex">${btn('A−','size-down','secondary')}<span id="size-value">${S.prefs.size*1.5}</span>${btn('A+','size-up','secondary')}</div></div><label class="field" style="margin-top:20px">Reading font<select data-pref="font">${['Charter','Iowan Old Style','Georgia','Palatino','Arial','Times New Roman','PingFang SC','Songti SC','Kaiti SC','Yuanti SC'].map(x=>`<option ${x===S.prefs.font?'selected':''}>${x}</option>`).join('')}</select></label><div class="field">Page tone<div class="flex" style="gap:16px;margin:9px 0">${[['#F8F8F8','Light'],['#E9E6D7','Warm'],['#373737','Dark gray'],['#000000','Black']].map(([c,t])=>`<button class="tone-choice ${S.prefs.tone===c?'selected':''}" style="background:${c};color:${c==='#F8F8F8'||c==='#E9E6D7'?'#1a1a1a':'#f2f2f2'}" data-action="tone:${c}" aria-label="${t}">A</button>`).join('')}</div></div><label class="field">Brightness preview<input type="range" min=".3" max="1" step=".05" value="1" id="brightness"></label><div class="note small">Browser brightness is a visual preview. Device-screen brightness is controlled by iOS.</div><div class="setting-row"><strong>Movement</strong><div class="tabs">${['Paged','Scroll'].map(x=>`<button class="${S.prefs.mode===x?'active':''}" data-action="movement:${x}">${x}</button>`).join('')}</div></div><div class="modal-footer">${btn('Done','close','primary','check')}</div>`)}
let speechOffset=0;
function speechText(){const b=book(reader.id);return paragraphs(b,reader.page).map((p,i)=>{if(S.prefs.redactions&&isRedacted(b,reader.page,i))return '';let ranges=S.ranges[b.id]?.[locKey(b,reader.page,i)]||[];if(S.prefs.redactions)for(const r of ranges.slice().sort((a,b)=>b.start-a.start))p=p.slice(0,r.start)+' '+p.slice(r.end);p=cleanText(p,b);for(const pr of S.pronunciations[b.id]||[]){let f={find:pr.word,mode:'Whole word',regex:false};p=p.replace(filterRegex(f),()=>pr.as)}return p}).join('\n\n')}
function stopSpeech(){speechToken++;playing=false;window.speechSynthesis?.cancel();$$('.spoken').forEach(x=>x.classList.remove('spoken'))}
function playSpeech(){if(!reader)return;if(S.engine==='kokoro'){toast('Kokoro requires a supported physical iOS device. Using a browser system voice.')}if(!window.speechSynthesis)return toast('Read-aloud is unavailable in this browser.');if(playing){speechSynthesis.pause();playing=false;render();return}if(speechSynthesis.paused){speechSynthesis.resume();playing=true;render();return}if(speechOffset>=speechText().length)speechOffset=0;const text=speechText(),baseOffset=speechOffset,utterance=new SpeechSynthesisUtterance(text.slice(baseOffset));utterance.rate=S.prefs.speed;utterance.pitch=S.prefs.pitch;utterance.voice=speechSynthesis.getVoices().find(v=>v.name===S.voice)||null;const token=++speechToken;utterance.onend=()=>{if(token!==speechToken)return;playing=false;speechOffset=0;if(reader.page<book(reader.id).total-1){turnPage(1);playSpeech()}else{book(reader.id).page=book(reader.id).total;save();render();toast('End of Book')}};utterance.onerror=e=>{if(!['interrupted','canceled'].includes(e.error)){playing=false;render();toast('Voice playback could not start. Try another system voice.')}};playing=true;chrome=true;render();utterance.onboundary=e=>{if(!reader||e.name!=='word'||token!==speechToken)return;$$('.spoken').forEach(el=>el.classList.remove('spoken'));speechOffset=baseOffset+e.charIndex;let spokenWord=text.slice(speechOffset).match(/^\S+/)?.[0]?.replace(/[^\p{L}\p{N}’'-]/gu,'');if(!spokenWord)return;let candidates=$$('.reading-page p:not(.redacted)');for(let p of candidates){let walker=document.createTreeWalker(p,NodeFilter.SHOW_TEXT),n;while((n=walker.nextNode())){let index=n.textContent.toLowerCase().indexOf(spokenWord.toLowerCase());if(index<0)continue;let range=document.createRange();range.setStart(n,index);range.setEnd(n,index+spokenWord.length);let span=document.createElement('span');span.className='spoken';range.surroundContents(span);return}}};speechSynthesis.speak(utterance)}
function voices(engine=S.engine){stopSpeech();if(reader)render();const voices=window.speechSynthesis?.getVoices()||[];modal('Choose Voice',`<div class="tabs"><button data-action="voice-engine:system" class="${engine==='system'?'active':''}">System Voices</button><button data-action="voice-engine:kokoro" class="${engine==='kokoro'?'active':''}">Premium Voices · Kokoro</button></div>${engine==='system'?`<p class="muted small" style="margin-bottom:18px">Voices available to this browser. In the iOS app, install additional voices under Settings → Accessibility → Read & Speak.</p>${voices.length?`<label class="field">Language & voice<select id="voice-select">${voices.map(v=>`<option value="${esc(v.name)}" ${S.voice===v.name?'selected':''}>${esc(v.name)} · ${esc(v.lang)}</option>`).join('')}</select></label>`:'<div class="note">No system voices are currently available. Try reloading after your browser has initialized speech.</div>'}<label class="field">Reading tone<select data-pref="pitch">${[.6,.8,1,1.2,1.4,1.7,2].map(x=>`<option ${x===S.prefs.pitch?'selected':''}>${x}</option>`).join('')}</select></label><div class="modal-footer">${btn('Preview','voice-preview','secondary','play')}${btn('Save Voice','voice-save','primary','check')}</div>`:`<div class="tour-art">${icon('headphones',48)}</div><h3>Natural voices, on your device.</h3><p class="muted small" style="margin:12px 0">54 voices across 9 language groups. The Kokoro model requires about 330 MB to download and 355 MB installed, plus temporary staging space.</p><div class="note">Kokoro synthesis requires a supported physical iOS device. It is unavailable in this browser prototype. You can explore the voice inventory below or use a system voice.</div><label class="field" style="margin-top:20px">Language / accent<select id="kokoro-language">${Object.keys(KOKORO).map(x=>`<option>${x}</option>`).join('')}</select></label><div id="kokoro-list">${kokoroList('English (United States)')}</div><div class="modal-footer">${btn('Use System Voices','voice-engine:system','primary')}</div>`}`);if(engine==='kokoro')$('#kokoro-language').onchange=e=>$('#kokoro-list').innerHTML=kokoroList(e.target.value);modalCleanup=()=>window.speechSynthesis?.cancel()}
const KOKORO={'English (United States)':['Alloy','Aoede','Bella','Heart','Jessica','Kore','Nicole','Nova','River','Sarah','Sky','Adam','Echo','Eric','Fenrir','Liam','Michael','Onyx','Puck','Santa'],'English (United Kingdom)':['Alice','Emma','Isabella','Lily','Daniel','Fable','George','Lewis'],'Spanish':['Dora','Alex','Santa'],'French (France)':['Siwis'],'Hindi':['Alpha (female)','Beta','Omega','Psi'],'Italian':['Sara','Nicola'],'Japanese':['Alpha (female)','Gongitsune','Nezumi','Tebukuro','Kumo'],'Portuguese (Brazil)':['Dora','Alex','Santa'],'Mandarin Chinese':['Xiaobei','Xiaoni','Xiaoxiao','Xiaoyi','Yunjian','Yunxi','Yunxia','Yunyang']};
function kokoroList(lang){return `<div class="tags">${KOKORO[lang].map(v=>`<span class="pill">${v}</span>`).join('')}</div><p class="small muted">${lang.startsWith('English')?'English pronunciation resource included.':'Additional multilingual pronunciation resource: about 82.6 MB.'}</p>`}
const categories=['Sexual Content','Nudity','Violence','Gore','Substance Use','Mature Themes','Self Harm','Horror'];
function review(id){const b=book(id);if(!b)return;guard(()=>showReview(id))}
function showReview(id){const b=book(id),red=(S.redacted[id]||[]).length+Object.values(S.ranges[id]||{}).filter(x=>x.length).length,tags=Object.values(S.tags[id]||{}).filter(x=>x.length).length;modal('Content Review',`<div class="detail-book">${cover(b)}<div><h2>${esc(b.title)}</h2><p>${esc(b.author)}</p><span class="pill">${icon('shield',12)} ${b.excluded?'Excluded from filtering':'Filtering enabled'}</span></div></div><div class="review-metrics"><div><strong>${tags}</strong><small>reviewed passages</small></div><div><strong>${red}</strong><small>manual redactions</small></div><div><strong>${Object.keys(S.limits[id]||{}).length}</strong><small>category limits</small></div></div><p class="muted small">Your choices stay with this book. Paragraphs above your allowed content level are hidden while reading.</p>${row('shield','Content Limits','Choose what feels right for this book.','limits:'+id)}${row('book','Browse Reviewed Paragraphs',`${tags} passages with manually saved tags`,'reviewed:'+id)}${row('edit','Manual Paragraph Redactions',`${red} saved redactions`,'redactions:'+id)}${row('share','Share Redactions','Export manual paragraph and text redactions.','export:redactions:'+id)}${row('share','Share Content Review','Export classifications and corrections.','export:ratings:'+id)}${row('filter',b.excluded?'Add to Filtering':'Remove from Filtering','Applies only to this book.','exclude:'+id)}${tags?row('refresh','Reset All Paragraph Changes','Restore the saved classification baseline.','reset-tags:'+id):''}${row('trash','Delete Content Review','Remove categories; keep book and manual redactions.','delete-review:'+id)}<div class="flex between" style="margin-top:23px">${btn('Delete Book','delete-book:'+id,'secondary danger','trash')}${btn('Open Book','read:'+id,'primary','book')}</div>`,true)}
function contentLimits(id){let tagged=[...new Set(Object.values(S.tags[id]||{}).flat().map(t=>t.category))];modal('Content Limits',`<p class="muted small" style="margin-bottom:15px">Paragraphs above the allowance are hidden. Limits change visibility without changing a paragraph’s saved classification.</p>${tagged.length?tagged.map(c=>`<div class="category-row"><strong style="font-size:12px">${c}</strong><span class="muted small">${Object.values(S.tags[id]||{}).filter(ts=>ts.some(t=>t.category===c)).length}</span><select data-limit="${c}" data-book="${id}" aria-label="${c} allowance">${['Blocked','Mild','Moderate','Strong'].map(x=>`<option ${x===(S.limits[id]?.[c]||'Strong')?'selected':''}>${x}</option>`).join('')}</select></div>`).join(''):empty('shield','No categories tagged yet.','Enter Parent Edit Mode and tap a paragraph to add a content category.',btn('Open Book','read:'+id))}<div class="note" style="margin-top:20px">Blocked: no present content · Mild: 11–39<br>Moderate: 40–79 · Strong: 80–100<br>Scores 0–10 indicate absent content.</div><p class="small muted" id="limits-count" style="margin-top:18px">${blockedCount(id)} reviewed paragraphs hidden with these limits.</p><div class="modal-footer">${btn('Back to Content Review','review-back:'+id,'secondary')}${btn('Done','close')}</div>`)}
function blockedCount(id){return Object.keys(S.tags[id]||{}).filter(key=>{let[p,i]=key.split(':').map(Number);return isBlocked(book(id),p,i)}).length}
function reviewed(id,category='All categories',severity='All severities'){let records=Object.entries(S.tags[id]||{}).filter(([key,tags])=>tags.length&&tags.some(t=>(category==='All categories'||t.category===category)&&(severity==='All severities'||band(t.severity)===severity)));modal('Browse Reviewed Paragraphs',`<div class="flex" style="margin-bottom:15px"><label class="field" style="flex:1">Category<select id="review-category">${['All categories',...categories].map(x=>`<option ${x===category?'selected':''}>${x}</option>`).join('')}</select></label><label class="field" style="flex:1">Severity<select id="review-severity">${['All severities','Absent','Mild','Moderate','Strong'].map(x=>`<option ${x===severity?'selected':''}>${x}</option>`).join('')}</select></label></div><p class="muted small">${records.length} matching passages</p>${records.map(([key,tags])=>{let[p,i]=key.split(':').map(Number);return `<button class="passage" data-action="passage:${id}:${p}:${i}"><small>Chapter ${p+1} · Paragraph ${i+1} · Manual classification</small><p style="margin-top:9px">${esc((paragraphs(book(id),p)[i]||'Passage unavailable').slice(0,180))}…</p><div class="tags">${tags.map(t=>`<span class="pill ${band(t.severity)==='Strong'?'red':band(t.severity)==='Moderate'?'orange':''}">${esc(t.category)} · ${t.severity}</span>`).join('')}</div></button>`}).join('')||empty('shield','No reviewed paragraphs','Add tags in Parent Edit Mode, or import a compatible Content Review package.')}<div class="modal-footer">${btn('Back','review-back:'+id,'secondary')}</div>`,true);$('#review-category').onchange=e=>reviewed(id,e.target.value,$('#review-severity').value);$('#review-severity').onchange=e=>reviewed(id,$('#review-category').value,e.target.value)}
function band(n){return n<=10?'Absent':n<=39?'Mild':n<=79?'Moderate':'Strong'}
function passageDetail(id,p,i){const b=book(id),text=paragraphs(b,p)[i]||'',key=locKey(b,p,i),tags=S.tags[id]?.[key]||[];modal('Review passage',`<p class="eyebrow muted">Chapter ${p+1} · Paragraph ${i+1}</p><div class="passage"><p>${esc(text)}</p></div><div class="flex between"><h3>Content categories</h3><span class="pill">Manual classification</span></div>${tags.map((t,n)=>`<div class="setting-row"><div style="flex:1"><strong>${esc(t.category)}</strong><p>Severity: <span id="severity-value-${n}">${t.severity}</span> · ${band(t.severity)} · Confidence ${t.confidence??100}%</p><input type="range" min="0" max="100" value="${t.severity}" data-tag-range="${n}" data-book="${id}" data-key="${key}" aria-label="${esc(t.category)} severity"></div>${ib('trash',`tag-delete:${id}:${p}:${i}:${n}`,'Remove category')}</div>`).join('')}<div class="flex between" style="margin:20px 0">${btn('Add Category Tag',`tag-add:${id}:${p}:${i}`,'secondary','plus')}${btn('Preview location',`preview:${id}:${p}`,'soft','book')}</div>${row('refresh','Reset to Saved Classification','Remove your manual changes for this paragraph.',`tag-reset:${id}:${p}:${i}`)}<div class="modal-footer">${btn('Done','close')}</div>`,true)}
function tagAdd(id,p,i){modal('Add Category Tag',`<form id="tag-form"><label class="field">Content category<select id="tag-category">${categories.map(c=>`<option>${c}</option>`).join('')}</select></label><label class="field">Severity (0–100)<input id="tag-severity" type="range" min="0" max="100" value="25"><span class="muted small" id="tag-readout">25 · Mild</span></label><p class="note">This is a manual classification. Confidence is recorded as 100% for your own correction.</p><div class="modal-footer">${btn('Cancel',`passage:${id}:${p}:${i}`,'secondary')}<button class="btn primary">Save category</button></div></form>`);$('#tag-severity').oninput=e=>$('#tag-readout').textContent=`${e.target.value} · ${band(+e.target.value)}`;$('#tag-form').onsubmit=e=>{e.preventDefault();S.tags[id]??={};let key=locKey(book(id),p,i),a=S.tags[id][key]||[],c=$('#tag-category').value;S.tags[id][key]=[...a.filter(t=>t.category!==c),{category:c,severity:+$('#tag-severity').value,confidence:100}];save();render();passageDetail(id,p,i)}}
function paragraphOptions(i){const id=reader.id,p=reader.page,b=book(id),key=locKey(b,p,i);modal('Redaction Options',`<div class="passage"><p>${esc(paragraphs(b,p)[i])}</p></div>${row('shield',(S.redacted[id]||[]).includes(key)?'Restore paragraph':'Redact whole paragraph','Saved edits apply when you leave Parent Edit Mode.',`redact:${id}:${p}:${i}`)}${row('edit','Redact selected text / Edit text redactions','Hide exact words while preserving surrounding text.',`text-redact:${id}:${p}:${i}`)}${row('filter','Change content categories','Set category, severity, and confidence.',`passage:${id}:${p}:${i}`)}${row('words','Training annotations','Development annotation/export tools.',`annotations:${id}:${p}:${i}`)}`,true)}
function textRedact(id,p,i){let b=book(id),key=locKey(b,p,i),text=paragraphs(b,p)[i],ranges=S.ranges[id]?.[key]||[],pos=0,html='';for(let r of ranges.slice().sort((a,b)=>a.start-b.start)){html+=esc(text.slice(pos,r.start))+`<mark>${esc(text.slice(r.start,r.end))}</mark>`;pos=r.end}html+=esc(text.slice(pos));modal('Edit text redactions',`<p class="muted small">Select the exact words to hide or restore. Existing redactions are shaded.</p><div class="passage" id="selection-text" style="font:18px/1.9 Georgia,serif;user-select:text">${html}</div><p class="muted small" id="selection-label">Select words in the paragraph above.</p><div class="modal-footer">${btn('Cancel','close','secondary')}<button class="btn primary" id="redact-selection" disabled>Redact Selection</button></div>`,true);let selected=null;$('#selection-text').onmouseup=$('#selection-text').ontouchend=()=>{setTimeout(()=>{const sel=window.getSelection();if(!sel.rangeCount||!$('#selection-text').contains(sel.anchorNode)||!$('#selection-text').contains(sel.focusNode))return;const r=sel.getRangeAt(0),before=r.cloneRange();before.selectNodeContents($('#selection-text'));before.setEnd(r.startContainer,r.startOffset);let raw=r.toString(),leading=raw.length-raw.trimStart().length,start=before.toString().length+leading,end=start+raw.trim().length;selected={start,end};let overlaps=ranges.some(x=>start<x.end&&end>x.start);$('#redact-selection').disabled=end<=start;$('#redact-selection').textContent=overlaps?'Un-redact Selection':'Redact Selection';$('#selection-label').textContent=raw.trim()?`Selected: “${raw.trim()}”`:'Select words in the paragraph above.'},20)};$('#redact-selection').onclick=()=>{if(!selected||selected.end<=selected.start)return;S.ranges[id]??={};let overlap=ranges.some(x=>selected.start<x.end&&selected.end>x.start);let next=overlap?ranges.filter(x=>!(selected.start<x.end&&selected.end>x.start)):[...ranges,selected];next.sort((a,b)=>a.start-b.start);let merged=[];for(const r of next){let last=merged.at(-1);if(last&&last.end>=r.start)last.end=Math.max(last.end,r.end);else merged.push({...r})}S.ranges[id][key]=merged;save();render();textRedact(id,p,i);toast(overlap?'Text restored':'Text redaction saved')}}
function redactions(id=reader?.id){let b=book(id),records=new Set([...(S.redacted[id]||[]),...Object.keys(S.ranges[id]||{}).filter(k=>S.ranges[id][k].length)]);modal('Manual Paragraph Redactions',`<p class="muted small">${records.size} saved passages in ${esc(b.title)}. Restoring a manual redaction does not change category limits.</p>${[...records].map(key=>{let[p,i]=key.split(':').map(Number);return `<div class="flex"><button class="passage" data-action="preview:${id}:${p}"><small>Chapter ${p+1} · ${S.redacted[id]?.includes(key)?'Whole paragraph':'Selected text'}</small><p>${esc((paragraphs(b,p)[i]||'').slice(0,140))}…</p></button><button class="text-btn danger" data-action="unredact:${id}:${p}:${i}">Un-redact</button></div>`}).join('')||empty('edit','No redactions yet','Enter Parent Edit Mode and tap a paragraph to make a redaction.')}<div class="modal-footer">${btn('Done','close')}</div>`,true)}
function searchBook(words=false){const b=book(reader.id);modal(words?'Review filtered words':'Search book',`${words?`<div class="setting-row"><strong>Show cleaned words</strong><button role="switch" aria-checked="true" class="toggle on" id="cleaned-review"><span></span></button></div>`:`<label class="search-field" style="margin-bottom:20px">${icon('search',17)}<input id="book-query" placeholder="Search within this book" aria-label="Search book"></label>`}<div id="book-search-results">${words?'':'<div class="empty"><p>Enter a word or phrase to find a passage.</p></div>'}</div>`,true);let showClean=true;function results(q){if(words&&b.excluded){$('#book-search-results').innerHTML='<div class="note">Re-enable filtering in Content Review to review filtered words.</div>';return}let matches=[];for(let p=0;p<b.total;p++)paragraphs(b,p).forEach((text,i)=>{let cleaned=cleanText(text,b);if(words?cleaned!==text:text.toLowerCase().includes(q.toLowerCase()))matches.push({p,i,text,cleaned})});$('#book-search-results').innerHTML=matches.slice(0,60).map(r=>`<button class="passage" data-action="preview:${b.id}:${r.p}"><small>Chapter ${r.p+1} · Paragraph ${r.i+1}</small><p>${esc((words&&showClean?r.cleaned:r.text).slice(0,210))}…</p></button>`).join('')||empty('search',words?'No active filter matches':'No matches found','Try another phrase or review your active filters.')}if(words){results('');$('#cleaned-review').onclick=e=>{showClean=!showClean;e.currentTarget.classList.toggle('on',showClean);e.currentTarget.setAttribute('aria-checked',showClean);results('')}}else{let timer;$('#book-query').oninput=e=>{clearTimeout(timer);let q=e.target.value.trim();if(!q){$('#book-search-results').innerHTML='<p class="muted">Enter a word or phrase to find a passage.</p>';return}$('#book-search-results').innerHTML='<div class="loading"></div>';timer=setTimeout(()=>results(q),250)}}}
function wordActions(word){modal(esc(word),`${row('volume','Modify Pronunciation','Change the spoken word in this book.','pronunciation-new:'+encodeURIComponent(word))}${row('book','Definition','Look up this word in your selected dictionary.','definition:'+encodeURIComponent(word))}${row('filter',S.filters.some(f=>{try{return filterRegex(f).test(word)}catch{return false}})?'Edit Filter':'Add to Filtered Words','Choose a cleaner replacement.','word-filter:'+encodeURIComponent(word))}`)}
function filterEditor(id,word=''){const old=S.filters.find(x=>x.id===id),f=old?{...old}:{id:'custom-'+Date.now(),find:word,replacement:'',enabled:true,regex:false,mode:'Whole word'};modal(old?'Edit Filter':'Add Filter',`<form id="filter-form"><label class="field">Word or phrase to clean<input id="find-text" value="${esc(f.find)}" placeholder="Word or phrase" required></label><label class="field">Replacement<input id="replacement-text" value="${esc(f.replacement)}" placeholder="A cleaner alternative" required></label><div class="setting-row" style="padding-top:0;margin-bottom:20px"><strong>Filter Enabled</strong><input type="checkbox" id="filter-enabled" ${f.enabled?'checked':''} style="accent-color:#708d5d;width:18px;height:18px"></div><label class="field">Match style<select id="match-mode">${['Anywhere in word','Whole word','Word start','Word end','Custom regex'].map(x=>`<option ${(f.regex?'Custom regex':f.mode)===x?'selected':''}>${x}</option>`).join('')}</select></label><div id="regex-boundaries" class="flex ${f.regex?'':'hidden'}" style="margin-bottom:20px"><label><input type="checkbox" id="match-start" ${f.start?'checked':''}> Word start</label><label><input type="checkbox" id="match-end" ${f.end?'checked':''}> Word end</label></div><label class="field">Try it in a sentence<textarea id="test-text">${esc(f.find?`The word is ${f.find}. Also try ${f.find}ing and un${f.find}.`:'Type a sentence to test your replacement.')}</textarea></label><div class="note" id="filter-preview">Your matching preview appears here.</div><div class="error" id="regex-error"></div><button type="button" class="text-btn" data-action="help-topic:Regex Filters">${icon('help',14)} Regex quick guide</button><div class="modal-footer">${btn('Cancel','close','secondary')}<button class="btn primary" id="save-filter">Save Filter</button></div></form>`);function draft(){return {...f,find:$('#find-text').value.trim(),replacement:$('#replacement-text').value.trim(),enabled:$('#filter-enabled').checked,regex:$('#match-mode').value==='Custom regex',mode:$('#match-mode').value,start:$('#match-start').checked,end:$('#match-end').checked}}function preview(){let d=draft();$('#save-filter').disabled=!d.find||!d.replacement;$('#regex-boundaries').classList.toggle('hidden',!d.regex);try{let re=filterRegex(d);$('#regex-error').textContent='';$('#filter-preview').textContent=d.find?$('#test-text').value.replace(re,m=>d.replacement?m[0]===m[0].toUpperCase()?d.replacement[0].toUpperCase()+d.replacement.slice(1):d.replacement[0].toLowerCase()+d.replacement.slice(1):'…'):$('#test-text').value}catch{$('#regex-error').textContent='Invalid regular expression. This rule will remain ineffective.';$('#filter-preview').textContent=$('#test-text').value}}$('#filter-form').oninput=preview;$('#filter-form').onchange=preview;preview();$('#filter-form').onsubmit=e=>{e.preventDefault();let d=draft();if(!d.find||!d.replacement)return;if(old)S.filters[S.filters.findIndex(x=>x.id===id)]=d;else S.filters.unshift(d);save();closeModal();render();toast('Filter saved. Your reading preferences are up to date.')}}
