function speakPreview(text,voice){if(!text)return;if(!window.speechSynthesis)return toast('Voice preview is unavailable.');speechSynthesis.cancel();let u=new SpeechSynthesisUtterance(text);u.voice=speechSynthesis.getVoices().find(v=>v.name===(voice||S.voice))||null;speechSynthesis.speak(u)}
