function wifi(){modal('Upload via WiFi',`<div class="tour-art">${icon('wifi',50)}</div><h2>${navigator.onLine?'Ready for upload · Preview':'Wi-Fi unavailable'}</h2><p class="muted small" style="margin:14px 0">Keep this screen open. In the iOS app, your computer and device must share a Wi-Fi network. Wait for each import to finish before uploading another.</p><div class="note"><strong>Browser prototype</strong><br>A local Wi-Fi upload server cannot run from this page. The address below is illustrative and is not a live endpoint.</div><div class="search-field" style="margin:20px 0"><input readonly value="http://192.168.1.24:8080" aria-label="Illustrative upload address"><button disabled class="text-btn">Copy Address</button></div>${btn('Choose a local file instead','choose-file','primary','upload')}`)}
function detail(id){const b=book(id);modal('A story to discover',`<div class="detail-book">${cover(b)}<div><span class="eyebrow muted">PROJECT GUTENBERG · SAMPLE</span><h2 style="margin-top:12px">${esc(b.title)}</h2><p>${esc(b.author)}</p><span class="pill">${esc(b.genre)}</span></div></div><p class="muted">${esc(b.summary)}</p><div class="tags"><span class="pill">English</span><span class="pill">${b.id==='brother'?'30142':'Classic literature'}</span><span class="pill">EPUB</span></div><div class="review-metrics"><div><strong>—</strong><small>Downloads · Not available</small></div><div><strong>—</strong><small>Reading ease · Not available</small></div><div><strong>${b.local?'✓':'Free'}</strong><small>${b.local?'In your library':'Sample preview'}</small></div></div><p class="note">${b.local?'This book is in your sample library.':'Add a sample excerpt to explore the reading workflow. This prototype does not download a full Gutenberg EPUB.'}${id==='brother'?' Bundled demo tags are attached only to this sample edition.':''}</p><div class="modal-footer">${btn('Done','close','secondary')}${btn(b.local?'Open Book':'Add sample to library',b.local?'read:'+id:'download:'+id,'primary',b.local?'book':'download')}</div>`,true)}
function downloadSample(id){guard(async()=>{if(!navigator.onLine){modal('Download Failed',`<p class="muted">You’re offline. Reconnect and try again. Your local library is still available.</p><div class="modal-footer">${btn('Retry','download:'+id)}${btn('Cancel','close','secondary')}</div>`);return}modal('Downloading book','<div class="loading"></div><p class="muted small" style="text-align:center">Simulating the EPUB download…</p>');let canceled=false;modalCleanup=()=>canceled=true;await new Promise(r=>setTimeout(r,700));if(canceled)return;$('.modal-header h2').textContent='Adding to library';await new Promise(r=>setTimeout(r,500));if(canceled)return;book(id).local=true;if(id==='brother'){S.tags[id]={'0:0':[{category:'Mature Themes',severity:45,confidence:95}]};S.baselines??={};S.baselines[id]=structuredClone(S.tags[id])}save();render();modal('Added to Library',`<div class="tour-art">${icon('check',52)}</div><h2>${esc(book(id).title)}</h2><p class="muted" style="margin-top:12px">The sample excerpt is now available on your bookshelf.${id==='brother'?' Demo content classifications were added.':''}</p><div class="modal-footer">${btn('Done','close','secondary')}${btn('Open Book','read:'+id,'primary','book')}</div>`)})}
function browse(scope='Books',query=''){exploreScope=scope;exploreQuery=query;modal(scope==='Search everything'?'Search Gutenberg':scope,`<label class="search-field" style="margin-bottom:20px">${icon('search',17)}<input id="catalog-query" placeholder="${scope==='Search everything'?'Search everything':'Search '+scope.toLowerCase()}" aria-label="Search Gutenberg catalog" value="${esc(query)}"></label><div class="tags" style="margin-bottom:20px">${['Search everything','Books','Authors','Subjects','Collections'].map(x=>`<button class="pill" data-action="browse:${x}" style="${scope===x?'background:var(--green);color:white':''}">${x}</button>`).join('')}</div><p class="muted small" style="margin-bottom:15px">Sample local catalog · ${S.books.length} titles</p><div id="catalog-results"></div>`,true);catalogResults(query);let timer;$('#catalog-query').oninput=e=>{clearTimeout(timer);let q=e.target.value;$('#catalog-results').innerHTML='<div class="loading"></div>';timer=setTimeout(()=>catalogResults(q),250)}}
function catalogResults(q){let filtered=S.books.filter(b=>`${b.title} ${b.author} ${b.genre}`.toLowerCase().includes(q.toLowerCase()));if(exploreScope==='Search everything'&&!q){$('#catalog-results').innerHTML=empty('search','What will you discover?','Start typing to search across Project Gutenberg.');return}let html='';if(['Books','Search everything'].includes(exploreScope))html=`<div class="eyebrow muted" style="margin:15px 0">Books</div>${filtered.map(b=>row('book',esc(b.title),esc(b.author),'detail:'+b.id)).join('')}`;if(['Authors','Search everything'].includes(exploreScope)){let authors=[...new Set(filtered.map(b=>b.author))];html+=`<div class="eyebrow muted" style="margin:22px 0 10px">Authors</div>${authors.map(a=>row('people',esc(a),`${S.books.filter(b=>b.author===a).length} books in sample catalog`,'author:'+encodeURIComponent(a))).join('')}`}if(['Subjects','Collections','Search everything'].includes(exploreScope)){let subjects=[...new Set(filtered.map(b=>b.genre))];html+=`<div class="eyebrow muted" style="margin:22px 0 10px">${exploreScope==='Collections'?'Collections':'Subjects'}</div>${subjects.map(g=>row('folder',esc(g),`${S.books.filter(b=>b.genre===g).length} books in sample catalog`,'subject:'+encodeURIComponent(g))).join('')}`}$('#catalog-results').innerHTML=filtered.length?html:empty('search','No results found','Try a different title, author, or topic.')}
function resources(){modal('Resources & downloads',`${[['catalog','Project Gutenberg catalog','70.8 MB archive'],['dictionary','Webster 1828 dictionary','7.9 MB archive'],['kokoro','Kokoro Premium Voices','330 MB download · 355 MB installed']].map(([id,title,size])=>`<div class="setting-row"><div><strong>${title}</strong><p>${size}</p><span class="pill" style="margin-top:8px">${id==='kokoro'?'Unavailable in browser':S.resources[id]==='ready'?'Ready · Sample resource':S.resources[id]==='failed'?'Download failed':'Not installed'}</span></div>${id==='kokoro'?btn('Details','voice-engine:kokoro','secondary'):btn(S.resources[id]==='ready'?'View state':'Retry Download','resource:'+id,'secondary','download')}</div>`).join('')}<p class="note" style="margin-top:20px">Catalog and dictionary installations are simulated independently. EPUB reading and saved preferences remain local.</p>`)}
function resourceFlow(id){modal(id==='catalog'?'Project Gutenberg catalog':'Webster 1828 dictionary',`<h2>Resource preview</h2><p class="muted small" style="margin:15px 0">Explore the preparing, downloading, failed, and ready states. This is a simulated resource installation.</p><div class="stack">${btn('Start download preview','resource-start:'+id,'primary','download')}${btn('Show download failure','resource-fail:'+id,'secondary')}${btn('Restore sample ready state','resource-ready:'+id,'secondary','check')}</div>`)}
async function startResource(id){if(!navigator.onLine){modal('Waiting for internet',`<p class="muted">Reconnect to download this resource. Your saved library is still available.</p><div class="modal-footer">${btn('Retry Download','resource-start:'+id)}${btn('Cancel','close','secondary')}</div>`);return}let cancel=false;modal('Downloading resource',`<div class="loading"></div><div class="progress" id="resource-progress"><span style="width:0%"></span></div><p class="muted small" style="text-align:center;margin-top:15px" id="resource-percent">Preparing…</p><div class="modal-footer">${btn('Cancel','close','secondary')}</div>`);modalCleanup=()=>cancel=true;for(let i=10;i<=100;i+=15){await new Promise(r=>setTimeout(r,150));if(cancel)return;$('#resource-progress span').style.width=i+'%';$('#resource-percent').textContent=i>=100?'Installing and validating…':i+'%'}await new Promise(r=>setTimeout(r,300));if(cancel)return;S.resources[id]='ready';save();render();resources();toast('Sample resource is ready.')}
const helpTopics={
'Getting Started':'Your reading space has four destinations: Home, Bookshelf, Explore, and Settings. Import an EPUB or open a sample book. The app remembers your reading location on this device.',
'Bookshelf':'Use Add Book to choose an EPUB from files. A book’s ellipsis opens Content Review and per-book actions. Delete Book requires confirmation. Sharing an EPUB itself is disabled.',
'Regex Filters':'Use Whole word for exact words, Word start for prefixes, Word end for suffixes, or Anywhere in word. Custom regex supports patterns such as darn(?:ed|ing)? and h[e3]ck. Turn start/end boundaries on independently. Simple match options treat punctuation literally. Test a sentence before saving. Replacements are literal text, not capture-group substitutions.',
'Explore':'Browse books, authors, subjects, and collections from the Gutenberg catalog. The native app downloads the catalog once, then searches locally. This prototype includes a small sample catalog and clearly labeled sample-add flows.',
'Filters':'Word filters change the displayed and spoken text. Use Settings → Edit Filters to add literal or regex rules, test replacements, enable or disable a rule, and share a package. Turn filtering off per book without deleting global rules.',
'Redactions':'Enter Parent Edit Mode from the reader menu, then tap a paragraph. Hide the whole paragraph, or select exact words in Edit text redactions. Category limits and manual redactions remain separate. Exit edit mode to see the reader’s concealed view.',
'Apple Intelligence':'AI Paragraph Summaries require iOS 26+, compatible hardware, Apple Intelligence enabled, and a downloaded model. They summarize hidden passages on-device. This browser cannot run Apple Intelligence, so it reports the unavailable state. AI-generated content classifications are disabled.',
'Content Review':'Open a book’s ellipsis in Bookshelf. Add manual category tags through Parent Edit Mode. Severity is 0–10 absent, 11–39 mild, 40–79 moderate, and 80–100 strong. A parent’s allowance changes visibility without changing tags. Import only matching EPUB editions.',
'Reading & Voice':'Tap a page to show or hide the controls. Use chapter arrows or Contents to navigate, and bookmark a page to keep it. Reader settings include font, text size, page tone, and Paged or Scroll movement. Browser system voices provide read-aloud. On iOS, install additional voices in Settings → Accessibility → Read & Speak. Premium Voices require the Kokoro model and a supported physical device.',
'Privacy & Parent Controls':'There are no reader accounts or cloud library synchronization. Personal changes are saved on this device. An optional 4-digit PIN protects editing, settings, and acquisition. Canceling authentication leaves the protected action unapplied. Browser PIN storage is only a prototype demonstration.'};
function help(){modal('Help & Tutorials',`<div class="note" style="margin-bottom:12px">A little guidance for every part of your reading space.</div>${row('leaf','App Setup Tour','A six-step introduction.','tour:0')}${row('settings','Prototype controls','Reset the sample and explore resource states.','prototype')}${Object.entries(helpTopics).map(([t])=>row('book',t,'','help-topic:'+t)).join('')}`)}
function helpArticle(topic){modal(esc(topic),`<article class="help-article"><h2>${esc(topic)}</h2><p style="margin-top:20px">${esc(helpTopics[topic]||helpTopics['Getting Started'])}</p><div class="setting-row"><strong>Show this tutorial automatically</strong><button id="tutorial-auto" class="toggle ${S.tutorials[topic]!==false?'on':''}" role="switch" aria-label="Show tutorial automatically" aria-checked="${S.tutorials[topic]!==false}"><span></span></button></div><div class="modal-footer">${btn('All help topics','help','secondary')}${btn('Got it','close','primary','check')}</div></article>`);$('#tutorial-auto').onclick=e=>{S.tutorials[topic]=S.tutorials[topic]===false;save();e.currentTarget.classList.toggle('on',S.tutorials[topic]);e.currentTarget.setAttribute('aria-checked',S.tutorials[topic])}}
let tourDraft={load:'keep',filters:true,goal:60};
function tour(step){const content=[['leaf','Welcome to a quieter kind of reading.','Keep the stories you love. Choose the words, passages, and reading experience that feel right for you.'],['shield','Keep the story. Choose the words.','Word filters replace selected words while you read and listen. Start small or choose the complete default list.'],['lock','A little extra peace of mind.','Optional PIN protection keeps editing and review tools in trusted hands. Ordinary reading stays easy.'],['headphones','Let the story come to you.','Read aloud with system voices. Premium Kokoro voices are available on a supported iOS device after a local download.'],['clock','Make a little time for yourself.','Choose a daily reading goal. Even a few quiet minutes can take you somewhere wonderful.'],['book','Your next chapter starts here.','Explore the sample library, add your own EPUB, or discover our featured Content Ratings book.']][step];modal('App Setup Tour',`<div class="flex between" style="margin-bottom:15px"><span class="eyebrow muted">STEP ${step+1} OF 6</span><button class="text-btn" data-action="tour-skip">Skip setup</button></div><div class="tour-art">${icon(content[0],60)}</div><h2>${content[1]}</h2><p class="muted" style="margin:15px 0 20px">${content[2]}</p>${step===1?`<label class="field">Filter list<select id="tour-list"><option value="keep">Keep my current filters</option><option value="starter">Load 10 starter filters</option><option value="full">Load all 157 default filters</option></select></label><div class="setting-row"><strong>Enable word filtering</strong><input type="checkbox" id="tour-filter" ${tourDraft.filters?'checked':''} style="accent-color:#708d5d"></div>`:step===2?`${btn(S.pin?'PIN protection is on':'Create a 4-digit PIN','tour-pin','secondary','lock')}<p class="muted small" style="margin-top:12px">You can also set this up later in Settings.</p>`:step===3?`<div class="note">System voices work in this browser. Kokoro and background iOS playback are device-only features.</div>`:step===4?`<div class="tabs">${[15,30,45,60].map(n=>`<button class="${tourDraft.goal===n?'active':''}" data-action="tour-goal:${n}">${n} min</button>`).join('')}</div>`:step===5?`${btn('View featured sample book','tour-sample','secondary','book')}`:''}<div class="flex between" style="margin-top:25px"><div class="tour-dots">${Array.from({length:6},(_,i)=>`<span class="${i===step?'active':''}"></span>`).join('')}</div><div class="flex">${step?btn('Back','tour:'+(step-1),'secondary'):''}${btn(step===5?'Start reading':'Next',step===5?'tour-finish':'tour:'+(step+1),'primary',step===5?'check':'arrow')}</div></div>`);if(step===1){$('#tour-list').value=tourDraft.load;$('#tour-list').onchange=e=>tourDraft.load=e.target.value;$('#tour-filter').onchange=e=>tourDraft.filters=e.target.checked}}
function finishTour(skip=false){if(!skip){S.prefs.goal=tourDraft.goal;S.prefs.filters=tourDraft.filters;if(tourDraft.load==='starter')S.filters=structuredClone(starter);if(tourDraft.load==='full')S.filters=structuredClone(DEFAULT_FILTERS)}S.setup=true;save();closeModal();render();toast(skip?'Setup skipped. Revisit it anytime in Help.':'Your reading space is ready.')}
function prototypeControls(){modal('Prototype controls',`<p class="muted small" style="margin-bottom:20px">Explore a browser-local concept with a sample library. Changes persist on this device. Native integrations are represented by explicit preview or unavailable states.</p>${row('download','Resource states','Preview catalog and dictionary downloads.','resources')}${row('leaf','Replay setup','Six-step onboarding tour.','tour:0')}${row('trash','Reset prototype','Restore the sample library and initial preferences.','prototype-reset')}<div class="note" style="margin-top:20px">The PIN is a visual prototype, not a security boundary. Import/export packages use a demo-only schema and are not compatible with the native app. No real Wi-Fi server or AI model runs here.</div>`)}
function handle(action){let [a,...parts]=action.split(':'),id=parts[0],p=+parts[1],i=+parts[2];switch(a){
case'nav':closeModal();return go(id);
case'close':return closeModal();
case'read':return openReader(id);
case'guard-filters':return guard(()=>go('filters'));
case'filters':return go('filters');
case'shelf-tab':shelfTab=id;return render();
case'global-search':return browse('Search everything');
case'add-book':return addBook();
case'choose-file':return chooseFile();
case'wifi':return wifi();
case'explore-close':closeModal();return go('explore');
case'detail':return detail(id);
case'download':return downloadSample(id);
case'browse':return browse(id);
case'author':{let name=decodeURIComponent(id),bs=S.books.filter(b=>b.author===name);return modal(esc(name),`<p class="muted small">${bs.length} titles in this sample catalog · Lifespan and aliases not available.</p>${bs.map(b=>row('book',esc(b.title),esc(b.genre),'detail:'+b.id)).join('')}`)}
case'subject':{let name=decodeURIComponent(id),bs=S.books.filter(b=>b.genre===name);return modal(esc(name),`<p class="muted small">A sample shelf of ${bs.length} ${esc(name.toLowerCase())} titles.</p>${bs.map(b=>row('book',esc(b.title),esc(b.author),'detail:'+b.id)).join('')}`)}
case'help':return help();
case'help-topic':return helpArticle(parts.join(':'));
case'tour':return tour(+id);
case'tour-pin':pinSetup();return;
case'tour-goal':tourDraft.goal=+id;return tour(4);
case'tour-sample':finishTour();return detail('brother');
case'tour-skip':return finishTour(true);
case'tour-finish':return finishTour();
case'goal':return modal('Daily Reading Goal',`<p class="muted" style="margin-bottom:20px">A gentle invitation to spend time with a story.</p><div class="stack">${[15,30,45,60].map(n=>btn(`${n} minutes ${n===S.prefs.goal?'✓':''}`,'set-goal:'+n,n===S.prefs.goal?'primary':'secondary','clock')).join('')}</div>`);
case'set-goal':S.prefs.goal=+id;save();closeModal();render();return toast('Daily reading goal updated.');
case'toggle':S.prefs[id]=!S.prefs[id];save();return render();
case'pin-manage':return S.pin?guard(()=>modal('Parent protection',`${row('edit','Change PIN','','pin-change')}${row('lock','Remove PIN','Turn off parent protection.','pin-remove')}`)):pinSetup();
case'pin-change':return pinSetup();
case'pin-remove':return confirmAction('Remove PIN?','Parent editing tools will no longer require your PIN.','Remove PIN',()=>{S.pin='';S.failures=0;toast('PIN protection removed.')});
case'filter-new':return filterEditor();
case'filter-edit':return filterEditor(id);
case'filter-toggle':{let f=S.filters.find(x=>x.id===id);if(f)f.enabled=!f.enabled;save();return render()}
case'filter-delete':return confirmAction('Delete Filter?','This rule will be removed from your filter list.','Delete Filter',()=>{S.filters=S.filters.filter(x=>x.id!==id)});
case'filters-enable':S.filters.forEach(f=>f.enabled=true);save();return render();
case'filter-more':return modal('Filter actions',`${row('refresh','Reset to Defaults','Replace your rules with the 157-rule built-in list.','filter-reset')}${row('plus','Add All Default Filters','Append missing definitions, keeping custom rules.','filter-append')}${row('upload','Import Filters','Merge or overwrite a compatible package.','choose-file')}${row('trash','Delete All Filters','Remove rules without changing your books.','filter-clear')}`);
case'filter-reset':return confirmAction('Reset to Defaults?','Replace all current filters with the complete 157-rule list? Your customizations will be lost.','Reset Filters',()=>{S.filters=structuredClone(DEFAULT_FILTERS);toast('157 default filters loaded.')});
case'filter-clear':return confirmAction('Delete All Filters?','Remove every filter rule? Existing books and redactions will stay saved.','Delete All',()=>{S.filters=[]});
case'filter-append':{let added=0;for(let f of DEFAULT_FILTERS)if(!S.filters.some(x=>x.find===f.find&&x.replacement===f.replacement&&x.mode===f.mode&&x.regex===f.regex)){S.filters.push({...f});added++}save();closeModal();render();return toast(`${added} default filters added.`)}
case'reader-close':creditReading();stopSpeech();speechOffset=0;if(reader&&!reader.review)book(reader.id).page=reader.page;reader=null;parent=false;save();return render();
case'reader-menu':return readerMenu();
case'reader-next':return turnPage(1);
case'reader-prev':return turnPage(-1);
case'bookmark':return bookmark();
case'bookmark-delete':S.bookmarks[reader.id].splice(+id,1);save();return contents('Bookmarks');
case'contents':return contents();
case'contents-tab':return contents(id);
case'chapter':creditReading();stopSpeech();reader.page=+id;speechOffset=0;if(!reader.review)book(reader.id).page=+id;pageStarted=Date.now();save();closeModal();chrome=true;return render();
case'appearance':return appearance();
case'size-up':case'size-down':S.prefs.size=Math.max(10,Math.min(30,S.prefs.size+(a==='size-up'?2:-2)));save();render();return appearance();
case'tone':S.prefs.tone=id;save();render();return appearance();
case'movement':S.prefs.mode=id;save();render();return appearance();
case'parent-enter':return guard(()=>{creditReading();parent=true;chrome=true;stopSpeech();closeModal();render();toast('Parent Edit Mode is on. Tap a paragraph to edit.')});
case'parent-exit':parent=false;pageStarted=Date.now();closeModal();return render();
case'parent-tools':return parentTools();
case'paragraph':return paragraphOptions(+id);
case'play':return playSpeech();
case'speech-stop':stopSpeech();speechOffset=0;render();return toast('Playback stopped.');
case'skip-back':case'skip-forward':{if(!reader)return;let text=speechText();speechOffset=Math.max(0,Math.min(text.length-1,speechOffset+(a==='skip-forward'?250:-250)));stopSpeech();return playSpeech()}
case'voices':return voices();
case'voice-engine':return voices(id);
case'voice-preview':{let preview=$('#voice-select')?.value;if(window.speechSynthesis?.speaking){speechSynthesis.cancel();return toast('Voice preview stopped.')}speakPreview('A little more peace on every page. Welcome to your reading space.',preview);return}
case'voice-save':S.voice=$('#voice-select')?.value||'';S.engine='system';save();closeModal();render();return toast('System voice saved.');
case'pronunciations':return pronunciations();
case'pronunciation-new':return pronunciationEditor(decodeURIComponent(id||''));
case'pronunciation-edit':return pronunciationEditor('',+id);
case'pronunciation-delete':S.pronunciations[reader.id].splice(+id,1);save();return pronunciations();
case'pronunciation-preview':return speakPreview($(id==='original'?'#pronunciation-word':'#pronunciation-as').value.trim());
case'pronunciation-transfer':return modal('Transfer Pronunciations',`${row('share','Export Pronunciations','Save a book-specific package.','export:pronunciations:'+reader.id)}${row('upload','Import Pronunciations','Choose a package and a target book.','choose-file')}${row('book','Copy to another book','Existing target entries win conflicts.','pronunciation-copy')}`);
case'pronunciation-copy':return modal('Copy to another book',`${localBooks().filter(b=>b.id!==reader.id).map(b=>row('book',esc(b.title),'','pronunciation-copy-to:'+b.id)).join('')||'<p class="muted">Add another book first.</p>'}`);
case'pronunciation-copy-to':mergePronunciations(id,S.pronunciations[reader.id]||[]);closeModal();return toast('Pronunciations copied. Existing target entries were kept.');
case'pronunciation-find':{let words=[...new Set(paragraphs(book(reader.id)).join(' ').match(/\b[A-Z][a-z]{4,}\b/g)||[])];return modal('Find Words in This Book',`<p class="muted small">Suggested names and uncommon words. Choose one to add a pronunciation.</p>${words.map(w=>row('volume',esc(w),'','pronunciation-new:'+encodeURIComponent(w))).join('')||'<p class="muted">No suggestions in this excerpt.</p>'}`)}
case'definition':{let word=decodeURIComponent(id);return modal(esc(word),`<span class="pill">${S.prefs.dictionary}</span><p class="muted" style="margin-top:18px">The native dictionary is unavailable in this browser. Open the dictionary link below to look up this word online.</p><div class="modal-footer"><a class="btn secondary" href="https://webstersdictionary1828.com/Dictionary/${encodeURIComponent(word)}" target="_blank" rel="noopener">Open Webster 1828 ${icon('arrow',15)}</a>${btn('Done','close')}</div>`)}
case'word-filter':{let word=decodeURIComponent(id),existing=S.filters.find(f=>{try{return filterRegex(f).test(word)}catch{return false}}),fn=()=>filterEditor(existing?.id,word);return S.pin&&((existing&&!parent)||(!existing&&S.prefs.authAdd))?guard(fn):fn()}
case'summary':return modal('AI Summary',`<div class="tour-art">${icon('spark',48)}</div><h2>Requires Apple Intelligence</h2><p class="muted" style="margin-top:15px">${S.prefs.summaries?'On-device summaries require iOS 26+, compatible hardware, and an available Apple Intelligence model. They cannot run in this browser.':'AI Paragraph Summaries are off in Settings.'}</p><p class="note" style="margin-top:15px">The hidden passage remains concealed. A summary is not available in this prototype.</p><div class="modal-footer">${btn('Learn more','help-topic:Apple Intelligence','secondary')}${btn('Done','close')}</div>`);
case'review':return review(id);
case'review-back':return showReview(id);
case'limits':return contentLimits(id);
case'reviewed':return reviewed(id);
case'passage':return passageDetail(id,p,i);
case'tag-add':return tagAdd(id,p,i);
case'tag-delete':{let key=locKey(book(id),p,i);S.tags[id][key].splice(+parts[3],1);save();render();return passageDetail(id,p,i)}
case'tag-reset':{let key=locKey(book(id),p,i);S.tags[id]??={};S.tags[id][key]=structuredClone(S.baselines?.[id]?.[key]||[]);save();render();return passageDetail(id,p,i)}
case'reset-tags':return confirmAction('Reset All Paragraph Changes?','Restore saved/imported classifications and remove manual corrections.','Reset Changes',()=>{S.tags[id]=structuredClone(S.baselines?.[id]||{})});
case'delete-review':return confirmAction('Delete Content Review?','Remove all classifications and content limits for this book? Your book and manual redactions remain.','Delete Review',()=>{delete S.tags[id];delete S.limits[id];delete S.baselines?.[id]});
case'exclude':{let b=book(id);b.excluded=!b.excluded;save();render();showReview(id);return toast(b.excluded?'Book removed from filtering.':'Book added to filtering.')}
case'delete-book':return confirmAction('Delete Book?',`Remove “${esc(book(id).title)}” and its saved book data from this device? Add the EPUB again to read it later.`,'Delete Book',()=>{if(reader?.id===id){stopSpeech();reader=null}if(seedBooks.some(b=>b.id===id)){let b=book(id);b.local=false;b.page=0;delete b.excluded}else S.books=S.books.filter(b=>b.id!==id);for(let k of ['bookmarks','redacted','ranges','limits','tags','pronunciations','baselines'])if(S[k])delete S[k][id];S.recent=S.recent.filter(x=>x!==id);if(S.current===id)S.current=localBooks()[0]?.id||'';page='shelf';toast('Book deleted from this device.')});
case'redactions':return redactions(id||reader.id);
case'redact':{let key=locKey(book(id),p,i),arr=S.redacted[id]||[];if(arr.includes(key))arr=arr.filter(x=>x!==key);else arr.push(key);S.redacted[id]=arr;save();closeModal();render();return toast('Paragraph redaction updated.')}
case'text-redact':return textRedact(id,p,i);
case'unredact':{let key=locKey(book(id),p,i);S.redacted[id]=(S.redacted[id]||[]).filter(x=>x!==key);if(S.ranges[id])delete S.ranges[id][key];save();render();return redactions(id)}
case'annotations':return modal('Training annotations',`<span class="pill orange">Development tool · Local only</span><p class="muted" style="margin:18px 0">Annotate this paragraph for a future training export. Nothing is uploaded or automatically classified.</p><label class="field">Annotation<textarea id="annotation-text" placeholder="Add a review note">${esc(S.annotations?.[id]?.[`${p}:${i}`]||'')}</textarea></label><div class="modal-footer"><button id="save-annotation" class="btn primary">Save annotation</button><button id="export-annotation" class="btn secondary">Export note</button></div>`),$('#save-annotation').onclick=()=>{S.annotations??={};S.annotations[id]??={};S.annotations[id][`${p}:${i}`]=$('#annotation-text').value.trim();save();closeModal();toast('Annotation saved locally.')},$('#export-annotation').onclick=()=>{let blob=new Blob([JSON.stringify({book:book(id).title,chapter:p,paragraph:i,note:$('#annotation-text').value},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='training-annotation.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
case'book-search':return searchBook();
case'review-words':return searchBook(true);
case'preview':stopSpeech();if(!reader||reader.id!==id)reader={id,page:p,review:true};else reader={...reader,page:p,review:true};parent=true;chrome=true;closeModal();return render();
case'open-here':reader.review=false;book(reader.id).page=reader.page;S.current=reader.id;save();render();return toast('Reading position moved to this chapter.');
case'export':return exportPackage(id,parts[1]);
case'resources':return resources();
case'resource':return resourceFlow(id);
case'resource-start':return startResource(id);
case'resource-ready':S.resources[id]='ready';save();render();return resources();
case'resource-fail':S.resources[id]='failed';save();render();return modal('Download failed',`<p class="muted">The sample download was interrupted. Other resources and your local library are unchanged.</p><div class="modal-footer">${btn('Retry Download','resource-start:'+id)}${btn('Cancel','close','secondary')}</div>`);
case'prototype':return prototypeControls();
case'prototype-reset':return confirmAction('Reset prototype?','Restore sample books and activity, and clear all changes in this browser. Export anything you want to keep first.','Reset Prototype',()=>{stopSpeech();reader=null;S=structuredClone(initial);page='home';save();toast('Prototype reset.')});
}}
document.addEventListener('click',e=>{let target=e.target.closest('[data-action]');if(target){e.preventDefault();handle(target.dataset.action);return}if(e.target.classList.contains('modal-backdrop'))closeModal();if(e.target.closest('.reader-body')&&!e.target.closest('button')&&!parent&&!window.getSelection()?.toString()){chrome=!chrome;let r=$('.reader');r?.classList.toggle('chrome-hidden',!chrome)}});
document.addEventListener('change',e=>{let target=e.target;if(target.dataset.pref){let key=target.dataset.pref;let restart=key==='speed'&&playing;if(restart)stopSpeech();S.prefs[key]=['size','goal','speed','pitch'].includes(key)?+target.value:target.value;save();let wasAppearance=$('#modal-title')?.textContent==='Reader settings';let oldScroll=$('#reader-body')?.scrollTop||0;render();if($('#reader-body'))$('#reader-body').scrollTop=oldScroll;if(wasAppearance)appearance();if(restart)playSpeech();return}if(target.dataset.limit){S.limits[target.dataset.book]??={};S.limits[target.dataset.book][target.dataset.limit]=target.value;save();if(reader)render();$('#limits-count').textContent=`${blockedCount(target.dataset.book)} reviewed paragraphs hidden with these limits.`}});
document.addEventListener('input',e=>{if(e.target.id==='shelf-search'){let field=e.target,pos=field.selectionStart;shelfQuery=field.value;render();$('#shelf-search').focus();$('#shelf-search').setSelectionRange(pos,pos)}if(e.target.id==='brightness'&&$('.reader'))$('.reader').style.filter=`brightness(${e.target.value})`;if(e.target.dataset.tagRange){let el=e.target,n=+el.dataset.tagRange;S.tags[el.dataset.book][el.dataset.key][n].severity=+el.value;save();$('#severity-value-'+n).textContent=el.value}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if($('.modal'))closeModal();else if(reader){chrome=true;render()}return}if((e.metaKey||e.ctrlKey)&&e.key==='k'){e.preventDefault();browse('Search everything')}if($('.modal')&&e.key==='Tab'){let focusable=$$('.modal button:not(:disabled), .modal input:not(:disabled), .modal select, .modal textarea, .modal a').filter(x=>x.offsetParent!==null),first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}if(reader&&!$('.modal')&&!['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName)){if(e.key==='ArrowRight')turnPage(1);if(e.key==='ArrowLeft')turnPage(-1);if(e.key===' '){e.preventDefault();playSpeech()}}});
let pressTimer,pressPoint,touchStart;
document.addEventListener('pointerdown',e=>{if(!reader||parent||!e.target.closest('.reading-page p:not(.redacted)'))return;pressPoint={x:e.clientX,y:e.clientY};touchStart=e.clientX;clearTimeout(pressTimer);pressTimer=setTimeout(()=>{if(!reader||parent)return;let range=document.caretRangeFromPoint?.(pressPoint.x,pressPoint.y);if(!range&&document.caretPositionFromPoint){let pos=document.caretPositionFromPoint(pressPoint.x,pressPoint.y);if(pos){range=document.createRange();range.setStart(pos.offsetNode,pos.offset)}}if(range&&range.startContainer.nodeType===3){let text=range.startContainer.textContent,offset=range.startOffset,left=text.slice(0,offset).match(/[\p{L}\p{N}’'-]+$/u)?.[0]||'',right=text.slice(offset).match(/^[\p{L}\p{N}’'-]+/u)?.[0]||'',word=left+right;if(word)wordActions(word)}},550)});
document.addEventListener('pointermove',e=>{if(pressPoint&&Math.abs(e.clientX-pressPoint.x)+Math.abs(e.clientY-pressPoint.y)>12)clearTimeout(pressTimer)});
document.addEventListener('pointerup',e=>{clearTimeout(pressTimer);if(reader&&!$('.modal')&&touchStart!=null&&Math.abs(e.clientX-touchStart)>80)turnPage(e.clientX<touchStart?1:-1);touchStart=null;pressPoint=null});
document.addEventListener('contextmenu',e=>{if(reader&&e.target.closest('.reading-page'))e.preventDefault()});
window.addEventListener('beforeunload',()=>{if(reader&&!reader.review)book(reader.id).page=reader.page;save();window.speechSynthesis?.cancel()});
window.addEventListener('online',()=>{render();toast('Back online. Your local changes are saved.')});window.addEventListener('offline',()=>{render();toast('Offline. Your saved books and preferences remain available.')});
render();

document.addEventListener('scroll',e=>{if(e.target.id==='reader-body'&&reader&&!reader.review&&S.prefs.mode==='Scroll'){S.scrollPositions??={};S.scrollPositions[reader.id+':'+reader.page]=e.target.scrollTop;save()}},true);

// The outer presentation controls only navigate the phone prototype.
window.addEventListener('message',event=>{
  if(event.source!==window.parent||event.data?.source!=='cleanbooks-preview')return;
  if(location.origin!=='null'&&event.origin!==location.origin)return;
  const {screen,tool}=event.data;
  if(screen&&['home','shelf','explore','settings'].includes(screen)){if(reader)handle('reader-close');closeModal();go(screen)}
  if(tool==='tour')tour(0);
  if(tool==='prototype')prototypeControls();
});
